//! Recovered client/UI translations that do not belong to the rules core.
//!
//! Selection overlays, command-card records, settings/string plumbing,
//! camera/gamma, renderer reporting and glue text.  They remain compiled
//! and tested as the auditable client reference; no simulation call site.

#![allow(
    clippy::unusual_byte_groupings,
    clippy::unnecessary_cast,
    clippy::too_many_arguments,
    clippy::collapsible_if,
    clippy::result_unit_err,
    clippy::byte_char_slices,
    clippy::while_let_loop,
    clippy::redundant_closure,
    clippy::manual_is_multiple_of,
    clippy::manual_repeat_n,
    clippy::assign_op_pattern,
    clippy::implicit_saturating_sub,
    clippy::if_same_then_else,
    clippy::doc_lazy_continuation,
    clippy::field_reassign_with_default,
    clippy::identity_op,
    clippy::neg_cmp_op_on_partial_ord,
    clippy::manual_range_patterns,
    clippy::needless_range_loop,
    clippy::erasing_op,
    clippy::bool_assert_comparison,
    clippy::chunks_exact_to_as_chunks,
    clippy::unnecessary_map_or,
    clippy::precedence,
    clippy::derivable_impls,
    clippy::manual_div_ceil
)]

use crate::combat::fp;
use crate::ids::unit as uid;
use crate::sim::{Order, SimError, SimUnit, World, is_door_type};
use std::sync::OnceLock;

// ===========================================================================
// Merged from src/translated/agent15.rs
// ===========================================================================
// Translation batch 15.  Only this file is edited by the batch.
//
// The batch covers the `decompiled_uncited` rows in
// `0x005b8000..=0x005bbfff` whose recovered body is at most 100 bytes and
// whose observable state is already modelled by [`crate::sim::World`] /
// [`crate::sim::SimUnit`].  Almost the whole block is the retail
// **ground-click command handler** plus the target-cursor state machine and
// a run of exception-unwind funclets, so only the click handlers are
// implemented here; the remaining rows are reported as skipped instead of
// being guessed at.
//
// Every click handler looks up a per-unit-type `orders.dat` row in one of
// the shipped byte tables (`0x00f8f2c8`, `0x00f8f3b0`, `0x00f8f498`,
// `0x00f8a450`) and then issues that row either against the clicked unit or
// at the clicked point.  Those tables are not part of
// [`crate::data::GameData`], so each entry point below takes the recovered
// row (and, for the gated variant, the gate byte) from its caller; the
// `CUnit+0x93` bit-0 write and the row dispatch itself are reproduced
// exactly through [`World::issue_order_id`].

impl World {
    /// Shared body of the recovered click handlers: set `CUnit+0x93` bit 0
    /// on the ordering unit and issue the recovered row with the clicked
    /// unit when one was hit, or with the clicked point otherwise.
    ///
    /// Retail performs the flag write before the dispatch in both branches
    /// (the target branch writes it inline, the point branch through the
    /// order-dispatch helper), so the Rust body does the same.
    fn a15_click_order_body(
        &mut self,
        unit_id: u32,
        order_row: u8,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<(), SimError> {
        let i = self.index_of(unit_id).ok_or(SimError::BadUnit)?;
        self.units[i].flags_93 |= 1;
        self.issue_order_id(unit_id, order_row, target, pos)
    }

    /// `0x005ba060` (`FUN_005ba060`, size 14): click handler for the
    /// per-unit-type row table at `0x00f8f2c8`.
    ///
    /// The body reads `row = table[unit type]` and branches on the clicked
    /// unit pointer.  With a unit target it sets `CUnit+0x93` bit 0 and
    /// issues `row` with both the position and the target; without a target
    /// it forwards the position to the same dispatch path (which performs
    /// the identical flag write).  The table lookup is replaced by the
    /// caller-supplied `order_row`; the remaining arguments are the clicked
    /// unit and point.
    pub fn a15_click_order_table_00f8f2c8(
        &mut self,
        unit_id: u32,
        order_row: u8,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<(), SimError> {
        self.a15_click_order_body(unit_id, order_row, target, pos)
    }

    /// `0x005ba08b` (`FUN_005ba08b`, size 14): second click handler,
    /// identical to [`Self::a15_click_order_table_00f8f2c8`] except that it
    /// reads the per-unit-type row from the table at `0x00f8f3b0`.
    ///
    /// Retail keeps one instantiation per table pointer; the Rust port takes
    /// the row from the caller because the table is not part of the data
    /// model.
    pub fn a15_click_order_table_00f8f3b0(
        &mut self,
        unit_id: u32,
        order_row: u8,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<(), SimError> {
        self.a15_click_order_body(unit_id, order_row, target, pos)
    }

    /// `0x005ba0b6` (`FUN_005ba0b6`, size 93): third click handler, the
    /// same target/point dispatch with the per-unit-type row read from the
    /// table at `0x00f8f498`.
    ///
    /// The routine is the largest of the four only because the compiler
    /// inlined the flag write and the two dispatch paths; the observable
    /// effect is the `CUnit+0x93` bit-0 write plus the row dispatch.
    pub fn a15_click_order_table_00f8f498(
        &mut self,
        unit_id: u32,
        order_row: u8,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<(), SimError> {
        self.a15_click_order_body(unit_id, order_row, target, pos)
    }

    /// `0x005ba0a0` (`FUN_005ba0a0`, size 22): gated click handler.
    ///
    /// Before dispatching, the body compares the caller's row byte with
    /// `table[type]` at `0x00f8f498` and reads the per-type gate byte from
    /// the second table at `0x00f8a450`; an unset gate makes the routine
    /// return without issuing anything.  The comparison's taken branch only
    /// re-reads the unit type, so it has no state effect.  The gate is taken
    /// as a caller-supplied boolean for the same reason as the row.
    ///
    /// Returns whether the order was issued.
    pub fn a15_click_order_gated(
        &mut self,
        unit_id: u32,
        order_row: u8,
        gate: bool,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<bool, SimError> {
        if !gate {
            return Ok(false);
        }
        self.a15_click_order_body(unit_id, order_row, target, pos)?;
        Ok(true)
    }

    /// `0x005ba343` (`FUN_005ba343`, size 38): continuation thunk that
    /// forwards four stack arguments (row, target and point) to the command
    /// row dispatcher and then unwinds its exception frame.
    ///
    /// The dispatcher is already modelled (it sets `CUnit+0x93` bit 0 and
    /// issues the row), so the thunk is exposed as a forwarding entry point
    /// with the same flag write; the unwind has no Rust equivalent.
    pub fn a15_forward_click_command(
        &mut self,
        unit_id: u32,
        order_row: u8,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<(), SimError> {
        self.a15_click_order_body(unit_id, order_row, target, pos)
    }
}

#[cfg(test)]
mod tests_agent15 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use crate::sim::Order;
    use std::sync::Arc;

    fn open_world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World, owner: usize, type_id: u16) -> u32 {
        let i = world.spawn(owner, type_id, 320, 320).unwrap();
        world.units[i].id
    }

    #[test]
    fn click_order_table_00f8f2c8_dispatches_target_and_point() {
        let mut w = open_world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        let zergling = spawn(&mut w, 1, uid::ZERGLING);

        // Clicked unit: the row goes out with the unit target.
        w.a15_click_order_table_00f8f2c8(marine, 8, Some(zergling), Some((400, 400)))
            .unwrap();
        let i = w.index_of(marine).unwrap();
        assert_eq!(w.units[i].order_row, 8);
        assert_eq!(w.units[i].order, Order::AttackUnit { target: zergling });
        assert_eq!(w.units[i].flags_93 & 1, 1, "CUnit+0x93 bit 0");

        // Clicked ground: the same flag write and a position order.
        let marine2 = spawn(&mut w, 0, uid::MARINE);
        w.a15_click_order_table_00f8f2c8(marine2, 6, None, Some((420, 420)))
            .unwrap();
        let j = w.index_of(marine2).unwrap();
        assert_eq!(w.units[j].order, Order::Move { pos: (420, 420) });
        assert_eq!(w.units[j].order_row, 6);
        assert_eq!(w.units[j].flags_93 & 1, 1);

        assert_eq!(
            w.a15_click_order_table_00f8f2c8(0xdead_beef, 6, None, Some((1, 1))),
            Err(SimError::BadUnit)
        );
    }

    #[test]
    fn click_order_table_00f8f3b0_issues_the_same_dispatch() {
        let mut w = open_world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        w.a15_click_order_table_00f8f3b0(marine, 6, None, Some((100, 200)))
            .unwrap();
        let i = w.index_of(marine).unwrap();
        assert_eq!(w.units[i].order, Order::Move { pos: (100, 200) });
        assert_eq!(w.units[i].order_row, 6);
        assert_eq!(w.units[i].flags_93 & 1, 1);
    }

    #[test]
    fn click_order_table_00f8f498_issues_a_hold_row_without_a_point() {
        let mut w = open_world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        w.a15_click_order_table_00f8f498(marine, 1, None, None)
            .unwrap();
        let i = w.index_of(marine).unwrap();
        assert_eq!(w.units[i].order, Order::HoldPosition);
        assert_eq!(w.units[i].order_row, 1);
        assert_eq!(w.units[i].flags_93 & 1, 1);
    }

    #[test]
    fn gated_click_order_needs_its_gate_byte() {
        let mut w = open_world();
        let marine = spawn(&mut w, 0, uid::MARINE);

        assert_eq!(
            w.a15_click_order_gated(marine, 6, false, None, Some((64, 64))),
            Ok(false)
        );
        let i = w.index_of(marine).unwrap();
        assert_eq!(w.units[i].order, Order::Idle);
        assert_eq!(w.units[i].flags_93, 0);

        assert_eq!(
            w.a15_click_order_gated(marine, 6, true, None, Some((64, 64))),
            Ok(true)
        );
        assert_eq!(w.units[i].order, Order::Move { pos: (64, 64) });
        assert_eq!(w.units[i].flags_93 & 1, 1);
    }

    #[test]
    fn forward_click_command_keeps_the_row_and_the_point() {
        let mut w = open_world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        w.a15_forward_click_command(marine, 6, None, Some((96, 128)))
            .unwrap();
        let i = w.index_of(marine).unwrap();
        assert_eq!(w.units[i].order, Order::Move { pos: (96, 128) });
        assert_eq!(w.units[i].order_row, 6);
        // The dispatcher sets the command flag before issuing the row.
        assert_eq!(w.units[i].flags_93 & 1, 1);
    }
}

// ===========================================================================
// Merged from src/translated/agent16.rs
// ===========================================================================
// Translation batch 16.  Only this file is edited by the batch.
//
// Routines recovered from `0x005c0000..=0x005c3fff`, the retail
// command-cursor / target-selection module.  Every item below names the exact
// decompiled entry address it reconstructs.
//
// The predicates in this range read four `CUnit` bytes that the Rust model
// does not store (`CUnit+0xdc` bits 1, 20 and 23, and the internal order byte
// at `CUnit+0x4d`).  They are supplied through [`A16UnitState`] rather than
// adding fields to [`SimUnit`]; every modelled field is read through the
// existing accessors.
//
// Several ledger rows in this range are not routine entries.  The decompiler
// split single routines at internal jump targets (`0x005c05f8` and
// `0x005c0631` inside `0x005c05d0`, `0x005c12e0` inside `0x005c12c0`,
// `0x005c23c9` inside `0x005c23a0`) or picked up mid-instruction addresses
// (`FUN_005c0229`, `FUN_005c0969`, `FUN_005c0d81`, `FUN_005c149c`, `FUN_005c315c`,
// `FUN_005c3cf4`, `FUN_005c3e11`).  The remaining rows (`FUN_005c03a4`,
// `FUN_005c0498`, `FUN_005c0b7f`, `FUN_005c1109`, `FUN_005c1148`) sit inside
// routines that are larger than this batch's size filter.  The routines
// translated here cover the internal chunk rows.

/// `CUnit` state the batch-16 target predicates read that [`SimUnit`] does
/// not model.
///
/// All three flags live in the retail `CUnit+0xdc` bit word and the order byte
/// is the retail "current order id" byte at `CUnit+0x4d`.  [`SimUnit`] keeps
/// `CUnit+0xdc` bits 19, 21, 22 and 26 and the numeric `orders.dat` row
/// ([`SimUnit::order_row`]); the values below are the remaining ones, passed
/// in by the caller so no persistent state is added.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct A16UnitState {
    /// `CUnit+0xdc` bit 1.  Gates the Larva candidate branch and
    /// short-circuits the pair-filter tail.
    pub bit_1: bool,
    /// `CUnit+0xdc` bit 20.  The candidate-side terminal condition of the
    /// near-cursor searches, and the entry gate of the gated variant.
    pub bit_20: bool,
    /// `CUnit+0xdc` bit 23.  One half of the shared pair-filter tail.
    pub bit_23: bool,
    /// `CUnit+0x4d`, the retail internal order byte.  The filters compare it
    /// with `0x52` (`'R'`), `0x54` (`'T'`) and `0x42` (`'B'`).
    pub order_byte: u8,
}

/// Result of the `CUnit+0xe2` target-retention step.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct A16TargetStep {
    /// Next value of the `CUnit+0xe2` state byte.
    pub state: u8,
    /// Sound cue the retail routine hands to its cue helper, if any.
    pub cue: Option<u16>,
}

fn a16_state(extras: &[A16UnitState], slot: usize) -> A16UnitState {
    extras.get(slot).copied().unwrap_or_default()
}

impl World {
    /// `0x005c12c0`: `units.dat` bounding-box intersection test.
    ///
    /// The routine takes the first unit's box from its own record (the four
    /// `units.dat` box extents read by [`World::unit_box_left`],
    /// [`World::unit_box_top`], [`World::unit_box_right`] and
    /// [`World::unit_box_bottom`]) and the second unit's box from an explicit
    /// type id.  With boxes `[x - left, x + right]` and
    /// `[y - top, y + bottom]` it returns true exactly when the two boxes
    /// overlap:
    ///
    /// * `x2 >= x1 - self.left - other.right`
    /// * `x2 <= x1 + self.right + other.left`
    /// * `y2 >= y1 - self.top - other.bottom`
    /// * `y2 <= y1 + self.bottom + other.top`
    ///
    /// Retail compares the four bounds as signed 16-bit values; world
    /// coordinates fit in `i16`, so the `i32` arithmetic here is exact.
    /// Also covers the interior ledger row `0x005c12e0`, a split of this
    /// routine's tail.
    pub fn a16_unit_boxes_overlap(
        &self,
        self_type: u16,
        self_at: (i32, i32),
        other_type: u16,
        other_at: (i32, i32),
    ) -> bool {
        let (x1, y1) = self_at;
        let (x2, y2) = other_at;
        x2 >= x1 - self.unit_box_left(self_type) - self.unit_box_right(other_type)
            && x2 <= x1 + self.unit_box_right(self_type) + self.unit_box_left(other_type)
            && y2 >= y1 - self.unit_box_top(self_type) - self.unit_box_bottom(other_type)
            && y2 <= y1 + self.unit_box_bottom(self_type) + self.unit_box_top(other_type)
    }

    /// `0x005c13d0`: "the point lies on the perimeter of the unit's click
    /// box".
    ///
    /// The unit's box comes from its own record (`left/top/right/bottom`
    /// half-extents around the pixel position) and is widened in place:
    ///
    /// * left edge  -= `right + 1`
    /// * right edge += `left + 1`
    /// * top edge   -= `bottom + 1`
    /// * the right edge is then grown again by `top + 1` (the retail code adds
    ///   the *top* extent to the right edge; that quirk is reproduced
    ///   verbatim, the bottom edge itself is left at `y + bottom`).
    ///
    /// A point passes when it sits on one of the two horizontal edges and
    /// within the other axis' span, or on one of the two vertical edges and
    /// within that span.  An interior point (on neither edge) fails.
    pub fn a16_point_on_unit_perimeter(&self, unit: usize, point: (i32, i32)) -> bool {
        let u = &self.units[unit];
        let left = self.unit_box_left(u.type_id);
        let right = self.unit_box_right(u.type_id);
        let top = self.unit_box_top(u.type_id);
        let bottom = self.unit_box_bottom(u.type_id);
        let x = u.x / fp(1);
        let y = u.y / fp(1);
        let lo_x = x - left - right - 1;
        let hi_x = x + right + left + top + 2;
        let lo_y = y - top - bottom - 1;
        let hi_y = y + bottom;
        let (px, py) = point;
        if px == lo_x || px == hi_x {
            return py >= lo_y && py <= hi_y;
        }
        if py == lo_y || py == hi_y {
            return px >= lo_x && px <= hi_x;
        }
        false
    }

    /// `0x005c1c00`: the shared pair filter used by the cursor searches.
    /// `a` is the candidate, `b` the unit that owns the search.
    ///
    /// 1. `a` flagged `CUnit+0xdc` bit 22 and `b` on the opposing side fails
    ///    (retail reads the alliance table through the `CUnit+0x4c` owners;
    ///    [`World::is_enemy`] is the model).
    /// 2. Larva (`units.dat` row `0x23`) and non-Larva never pass each other;
    ///    a Larva candidate additionally requires `a`'s `CUnit+0xdc` bit 1.
    /// 3. With `b`'s bit 23 clear the pair passes, and with `a`'s bit 1 set it
    ///    passes as well.
    /// 4. Otherwise `a` needs bit 23, `b`'s order byte must not be `0x54`
    ///    (`'T'`) and the result is `a`'s order byte being `0x52` (`'R'`).
    pub fn a16_pair_filter(
        &self,
        a: &SimUnit,
        a_state: A16UnitState,
        b: &SimUnit,
        b_state: A16UnitState,
    ) -> bool {
        if a.flag_22() && self.is_enemy(a.owner, b.owner) {
            return false;
        }
        if b.type_id == uid::LARVA && !a_state.bit_1 {
            return false;
        }
        if b.type_id != uid::LARVA && a.type_id == uid::LARVA {
            return false;
        }
        if !b_state.bit_23 {
            return true;
        }
        if a_state.bit_1 {
            return true;
        }
        if !a_state.bit_23 {
            return false;
        }
        if b_state.order_byte == 0x54 {
            return false;
        }
        a_state.order_byte == 0x52
    }

    /// `0x005c1b40`: search-side wrapper around [`World::a16_pair_filter`].
    ///
    /// The unit must carry `CUnit+0x105` bit 0 and must not have
    /// `CUnit+0xdc` bit 21.  A null `other` passes, an `other` equal to the
    /// unit itself fails, and otherwise the pair filter decides.
    pub fn a16_target_filter(
        &self,
        unit: usize,
        other: Option<usize>,
        extras: &[A16UnitState],
    ) -> bool {
        let a = &self.units[unit];
        if !a.flag_105_bit0() || a.flag_21() {
            return false;
        }
        let Some(other) = other else {
            return true;
        };
        if other == unit {
            return false;
        }
        let b = &self.units[other];
        self.a16_pair_filter(a, a16_state(extras, unit), b, a16_state(extras, other))
    }

    /// `0x005c1380`: the command cursor's "this unit may be the target of the
    /// pending command" gate.
    ///
    /// The routine runs only while the unit has arrived at its move target
    /// (the retail `CUnit+0x10`/`+0x12` pixel pair matches the unit position,
    /// modelled by [`SimUnit::path_goal`] pointing at the unit's own
    /// position), or the unit is the pending command target (the
    /// pending-target global), or the caller forces the check (the forcing
    /// global).
    /// It then rejects the four door types (`0xcd..=0xd0`) and applies
    /// [`World::a16_target_filter`].
    pub fn a16_command_target_allowed(
        &self,
        unit: usize,
        other: Option<usize>,
        pending: Option<usize>,
        force: bool,
        extras: &[A16UnitState],
    ) -> bool {
        let u = &self.units[unit];
        let at_target = u.path_goal == Some((u.x, u.y));
        if !(at_target || pending == Some(unit) || force) {
            return false;
        }
        if is_door_type(u.type_id) {
            return false;
        }
        self.a16_target_filter(unit, other, extras)
    }

    /// `0x005c05d0`: find a unit near the cursor that the owning unit may act
    /// on.
    ///
    /// The retail routine asks the shared spatial-grid cursor (the retail
    /// grid query) for the units in the grid line between the unit and
    /// the cursor, keeps the candidates that carry `CUnit+0x105` bit 0, do
    /// not have `CUnit+0xdc` bit 21, are not the owning unit itself and pass
    /// [`World::a16_pair_filter`], and returns the first one whose
    /// `CUnit+0xdc` bit 20 is set.  The grid cursor and its scratch list are
    /// global state the Rust world does not keep, so this translation scans
    /// the rectangle spanned by the unit and the cursor in slot order; the
    /// caller only distinguishes "found" from "not found".  Also covers the
    /// interior ledger rows `0x005c05f8` and `0x005c0631`, splits of this
    /// routine's filter loop.
    pub fn a16_find_target_near_cursor(
        &self,
        unit: usize,
        cursor: (i32, i32),
        extras: &[A16UnitState],
    ) -> Option<u32> {
        let owner = &self.units[unit];
        let from = (owner.x / fp(1), owner.y / fp(1));
        let (x0, x1) = if from.0 <= cursor.0 {
            (from.0, cursor.0)
        } else {
            (cursor.0, from.0)
        };
        let (y0, y1) = if from.1 <= cursor.1 {
            (from.1, cursor.1)
        } else {
            (cursor.1, from.1)
        };
        for (slot, cand) in self.units.iter().enumerate() {
            if !cand.alive || slot == unit {
                continue;
            }
            let at = (cand.x / fp(1), cand.y / fp(1));
            if at.0 < x0 || at.0 > x1 || at.1 < y0 || at.1 > y1 {
                continue;
            }
            if !cand.flag_105_bit0() || cand.flag_21() {
                continue;
            }
            let cand_state = a16_state(extras, slot);
            if !self.a16_pair_filter(cand, cand_state, owner, a16_state(extras, unit)) {
                continue;
            }
            if cand_state.bit_20 {
                return Some(cand.id);
            }
        }
        None
    }

    /// `0x005c0730`: [`World::a16_find_target_near_cursor`] behind the
    /// `CUnit+0xdc` bit-20 entry gate.
    ///
    /// The only difference from the ungated search is the first check: the
    /// searching unit must itself have bit 20 set, otherwise the routine
    /// returns null before it touches the grid.
    pub fn a16_find_target_near_cursor_gated(
        &self,
        unit: usize,
        cursor: (i32, i32),
        extras: &[A16UnitState],
    ) -> Option<u32> {
        if !a16_state(extras, unit).bit_20 {
            return None;
        }
        self.a16_find_target_near_cursor(unit, cursor, extras)
    }
}

/// `0x005c1820`: select entry `index` from a variable-length word table.
///
/// The retail table starts with a `u16` count, then one reserved word, then
/// the entries; the routine stores the requested index, rejects the request
/// when `index > count`, and stores the selected entry when it is nonzero.
/// It returns whether an entry was selected and the selected value, so the
/// index and selection globals it would write stay with the caller.
pub fn a16_select_indexed_entry(count: u16, entries: &[u16], index: u8) -> Option<u16> {
    let entry = *entries.get(usize::from(index))?;
    (u16::from(index) <= count && entry != 0).then_some(entry)
}

impl SimUnit {
    /// `0x005c23a0`: three-state target-retention step for `CUnit+0xe2`.
    ///
    /// State 0 with a live `CUnit+0x5c` target ([`SimUnit::order_unit_target`])
    /// plays cue `0x13` and moves to state 1.  State 1 keeps the target while
    /// the target's `CUnit+0x4d` order byte is `0x42` (`'B'`); otherwise it
    /// drops the target and moves to state 2.  State 2 plays cue `0x14` and
    /// returns to state 0 when there is no target, and goes back to state 1
    /// while a target is present.  Any other state value is left alone.
    ///
    /// Dropping the target clears the order, matching the retail store of zero
    /// into `CUnit+0x5c`; the state byte itself is returned instead of being
    /// stored because [`SimUnit`] has no `CUnit+0xe2` field.  Also covers the
    /// interior ledger row `0x005c23c9`, a split inside this routine.
    pub fn a16_target_state_step(&mut self, state: u8, target_order_byte: u8) -> A16TargetStep {
        let has_target = self.order_unit_target().is_some();
        let (next, cue) = match state {
            0 => {
                if has_target {
                    (1, Some(0x13))
                } else {
                    (0, None)
                }
            }
            1 => {
                if !has_target {
                    (2, None)
                } else if target_order_byte == 0x42 {
                    (1, None)
                } else {
                    self.order = Order::Idle;
                    (2, None)
                }
            }
            2 => {
                if has_target {
                    (1, None)
                } else {
                    (0, Some(0x14))
                }
            }
            other => (other, None),
        };
        A16TargetStep { state: next, cue }
    }
}

#[cfg(test)]
mod tests_agent16 {
    use super::*;
    use crate::data::GameData;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World, owner: usize, type_id: u16, x: i32, y: i32) -> usize {
        world.spawn(owner, type_id, x, y).expect("spawn")
    }

    fn state(bit_1: bool, bit_20: bool, bit_23: bool, order_byte: u8) -> A16UnitState {
        A16UnitState {
            bit_1,
            bit_20,
            bit_23,
            order_byte,
        }
    }

    #[test]
    fn boxes_overlap_uses_the_units_dat_extents() {
        let w = world();
        let t = uid::MARINE;
        let l = w.unit_box_left(t);
        let r = w.unit_box_right(t);
        let top = w.unit_box_top(t);
        let bottom = w.unit_box_bottom(t);
        assert!(l > 0 && r > 0 && top > 0 && bottom > 0);

        assert!(w.a16_unit_boxes_overlap(t, (100, 100), t, (100, 100)));
        // Exactly touching on the right/left and bottom/top edges.
        assert!(w.a16_unit_boxes_overlap(t, (100, 100), t, (100 + r + l, 100)));
        assert!(w.a16_unit_boxes_overlap(t, (100, 100), t, (100 - r - l, 100)));
        assert!(w.a16_unit_boxes_overlap(t, (100, 100), t, (100, 100 + bottom + top)));
        assert!(w.a16_unit_boxes_overlap(t, (100, 100), t, (100, 100 - bottom - top)));
        // One pixel of separation on each axis.
        assert!(!w.a16_unit_boxes_overlap(t, (100, 100), t, (100 + r + l + 1, 100)));
        assert!(!w.a16_unit_boxes_overlap(t, (100, 100), t, (100 - r - l - 1, 100)));
        assert!(!w.a16_unit_boxes_overlap(t, (100, 100), t, (100, 100 - bottom - top - 1)));
        // A large building's box reaches a marine further away.
        let cc = uid::COMMAND_CENTER;
        let gap = 100 + w.unit_box_right(cc) + l;
        assert!(w.a16_unit_boxes_overlap(cc, (100, 100), t, (gap, 100)));
        assert!(!w.a16_unit_boxes_overlap(cc, (100, 100), t, (gap + 1, 100)));
    }

    #[test]
    fn perimeter_test_accepts_edge_points_only() {
        let mut w = world();
        let slot = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let t = w.units[slot].type_id;
        let l = w.unit_box_left(t);
        let r = w.unit_box_right(t);
        let top = w.unit_box_top(t);
        let bottom = w.unit_box_bottom(t);
        let lo_x = 100 - l - r - 1;
        let hi_x = 100 + r + l + top + 2;
        let lo_y = 100 - top - bottom - 1;
        let hi_y = 100 + bottom;
        assert!(lo_x < 100 && 100 < hi_x && lo_y < 100 && 100 < hi_y);

        assert!(w.a16_point_on_unit_perimeter(slot, (lo_x, 100)));
        assert!(w.a16_point_on_unit_perimeter(slot, (hi_x, 100)));
        assert!(w.a16_point_on_unit_perimeter(slot, (100, lo_y)));
        assert!(w.a16_point_on_unit_perimeter(slot, (100, hi_y)));
        // Interior points are not on the perimeter.
        assert!(!w.a16_point_on_unit_perimeter(slot, (100, 100)));
        // Corner combinations outside the orthogonal span fail.
        assert!(!w.a16_point_on_unit_perimeter(slot, (lo_x, lo_y - 1)));
        assert!(!w.a16_point_on_unit_perimeter(slot, (hi_x + 1, 100)));
        assert!(!w.a16_point_on_unit_perimeter(slot, (100 + bottom + 1, 100)));
    }

    #[test]
    fn pair_filter_follows_the_retail_chain() {
        let mut w = world();
        let a = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let b = spawn(&mut w, 0, uid::MARINE, 200, 200);
        let d = A16UnitState::default();
        assert!(w.a16_pair_filter(&w.units[a], d, &w.units[b], d));

        // bit 22 plus an enemy owner fails; the same side continues.
        let mut held = w.units[a].clone();
        held.flag_22 = true;
        let mut enemy = w.units[b].clone();
        enemy.owner = 1;
        assert!(!w.a16_pair_filter(&held, d, &enemy, d));
        assert!(w.a16_pair_filter(&held, d, &w.units[b], d));
    }

    #[test]
    fn pair_filter_treats_larva_as_its_own_class() {
        let mut w = world();
        let a = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let larva = spawn(&mut w, 0, uid::LARVA, 120, 120);
        let d = A16UnitState::default();
        // A Larva candidate needs bit 1 on the searching unit.
        assert!(!w.a16_pair_filter(&w.units[a], d, &w.units[larva], d));
        assert!(w.a16_pair_filter(
            &w.units[a],
            state(true, false, false, 0),
            &w.units[larva],
            d
        ));
        // A Larva search unit never matches a non-Larva candidate.
        assert!(!w.a16_pair_filter(
            &w.units[larva],
            state(true, false, false, 0),
            &w.units[a],
            d
        ));
        // Larva against Larva is decided by the tail only.
        assert!(w.a16_pair_filter(
            &w.units[larva],
            state(true, false, false, 0),
            &w.units[larva],
            d
        ));
    }

    #[test]
    fn pair_filter_tail_uses_bits_23_and_the_order_byte() {
        let mut w = world();
        let a = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let b = spawn(&mut w, 0, uid::MARINE, 200, 200);
        let none = A16UnitState::default();
        // Candidate bit 23 clear: always passes.
        assert!(w.a16_pair_filter(&w.units[a], none, &w.units[b], none));
        // Searching unit bit 1 short-circuits the tail.
        assert!(w.a16_pair_filter(
            &w.units[a],
            state(true, false, false, 0),
            &w.units[b],
            state(false, false, true, 0)
        ));
        // Candidate bit 23 set, unit bit 1 clear, unit bit 23 clear: fails.
        assert!(!w.a16_pair_filter(&w.units[a], none, &w.units[b], state(false, false, true, 0)));
        // Unit bit 23 set, candidate order byte 'T': fails.
        assert!(!w.a16_pair_filter(
            &w.units[a],
            state(false, false, true, 0x52),
            &w.units[b],
            state(false, false, true, 0x54)
        ));
        // Unit order byte 'R' passes, anything else fails.
        assert!(w.a16_pair_filter(
            &w.units[a],
            state(false, false, true, 0x52),
            &w.units[b],
            state(false, false, true, 0)
        ));
        assert!(!w.a16_pair_filter(
            &w.units[a],
            state(false, false, true, 0x51),
            &w.units[b],
            state(false, false, true, 0)
        ));
    }

    #[test]
    fn target_filter_checks_the_unit_flags_first() {
        let mut w = world();
        let unit = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let other = spawn(&mut w, 0, uid::MARINE, 120, 100);
        assert!(!w.a16_target_filter(unit, Some(other), &[]));
        w.units[unit].flags_105 = 1;
        assert!(w.a16_target_filter(unit, Some(other), &[]));
        assert!(w.a16_target_filter(unit, None, &[]));
        assert!(!w.a16_target_filter(unit, Some(unit), &[]));
        w.units[unit].flag_21 = true;
        assert!(!w.a16_target_filter(unit, Some(other), &[]));
        assert!(!w.a16_target_filter(unit, None, &[]));
    }

    #[test]
    fn command_gate_requires_arrival_pending_or_force() {
        let mut w = world();
        let unit = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let other = spawn(&mut w, 0, uid::MARINE, 120, 100);
        w.units[unit].flags_105 = 1;
        assert!(!w.a16_command_target_allowed(unit, Some(other), None, false, &[]));
        assert!(w.a16_command_target_allowed(unit, Some(other), Some(unit), false, &[]));
        assert!(w.a16_command_target_allowed(unit, Some(other), None, true, &[]));
        // Arriving at the stored move target opens the gate as well.
        let pos = (w.units[unit].x, w.units[unit].y);
        w.units[unit].path_goal = Some(pos);
        assert!(w.a16_command_target_allowed(unit, Some(other), None, false, &[]));
        // A door unit is never a valid command target.
        let door = spawn(&mut w, 0, 0xcd, 140, 100);
        w.units[door].flags_105 = 1;
        w.units[door].path_goal = Some((w.units[door].x, w.units[door].y));
        assert!(!w.a16_command_target_allowed(door, Some(other), None, false, &[]));
    }

    #[test]
    fn near_cursor_search_returns_the_first_armed_candidate() {
        let mut w = world();
        let unit = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let cand = spawn(&mut w, 0, uid::MARINE, 120, 100);
        w.units[cand].flags_105 = 1;
        let extras = [A16UnitState::default(), state(false, true, false, 0)];
        assert_eq!(
            w.a16_find_target_near_cursor(unit, (130, 100), &extras),
            Some(w.units[cand].id)
        );
        // Candidate bit 20 clear: no result.
        assert_eq!(w.a16_find_target_near_cursor(unit, (130, 100), &[]), None);
        // Candidate outside the unit/cursor rectangle: no result.
        assert_eq!(
            w.a16_find_target_near_cursor(unit, (100, 200), &extras),
            None
        );
        // Candidate flag 21 blocks the search.
        w.units[cand].flag_21 = true;
        assert_eq!(
            w.a16_find_target_near_cursor(unit, (130, 100), &extras),
            None
        );
    }

    #[test]
    fn gated_near_cursor_search_needs_bit_20_on_the_searching_unit() {
        let mut w = world();
        let unit = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let cand = spawn(&mut w, 0, uid::MARINE, 120, 100);
        w.units[cand].flags_105 = 1;
        let inert = [A16UnitState::default(), state(false, true, false, 0)];
        assert_eq!(
            w.a16_find_target_near_cursor_gated(unit, (130, 100), &inert),
            None
        );
        let active = [state(false, true, false, 0), state(false, true, false, 0)];
        assert_eq!(
            w.a16_find_target_near_cursor_gated(unit, (130, 100), &active),
            Some(w.units[cand].id)
        );
    }

    #[test]
    fn indexed_table_selection_rejects_out_of_range_and_zero_entries() {
        let entries = [5u16, 0, 7, 9];
        assert_eq!(a16_select_indexed_entry(3, &entries, 0), Some(5));
        assert_eq!(a16_select_indexed_entry(3, &entries, 1), None);
        assert_eq!(a16_select_indexed_entry(3, &entries, 2), Some(7));
        assert_eq!(a16_select_indexed_entry(3, &entries, 3), Some(9));
        assert_eq!(a16_select_indexed_entry(2, &entries, 3), None);
        assert_eq!(a16_select_indexed_entry(9, &entries, 4), None);
    }

    #[test]
    fn target_state_machine_plays_cues_and_drops_stale_targets() {
        let mut w = world();
        let unit = spawn(&mut w, 0, uid::MARINE, 100, 100);
        let victim = spawn(&mut w, 1, uid::MARINE, 120, 100);
        let victim_id = w.units[victim].id;

        // State 0 without a target does nothing.
        assert_eq!(
            w.units[unit].a16_target_state_step(0, 0),
            A16TargetStep {
                state: 0,
                cue: None
            }
        );
        // State 0 with a target arms the cue and advances.
        w.units[unit].order = Order::AttackUnit { target: victim_id };
        assert_eq!(
            w.units[unit].a16_target_state_step(0, 0),
            A16TargetStep {
                state: 1,
                cue: Some(0x13)
            }
        );
        // State 1 keeps a target whose order byte is 'B'.
        assert_eq!(
            w.units[unit].a16_target_state_step(1, 0x42),
            A16TargetStep {
                state: 1,
                cue: None
            }
        );
        assert!(w.units[unit].order_unit_target().is_some());
        // Any other order byte drops the target and moves on.
        assert_eq!(
            w.units[unit].a16_target_state_step(1, 0x00),
            A16TargetStep {
                state: 2,
                cue: None
            }
        );
        assert_eq!(w.units[unit].order_unit_target(), None);
        // State 2 without a target fires the second cue and resets.
        assert_eq!(
            w.units[unit].a16_target_state_step(2, 0),
            A16TargetStep {
                state: 0,
                cue: Some(0x14)
            }
        );
        // State 2 with a target returns to state 1.
        w.units[unit].order = Order::AttackUnit { target: victim_id };
        assert_eq!(
            w.units[unit].a16_target_state_step(2, 0),
            A16TargetStep {
                state: 1,
                cue: None
            }
        );
        // Unknown states are ignored.
        assert_eq!(
            w.units[unit].a16_target_state_step(7, 0x42),
            A16TargetStep {
                state: 7,
                cue: None
            }
        );
    }
}

// ===========================================================================
// Merged from src/translated/agent17.rs
// ===========================================================================
// Translation batch 17.  Only this file is edited by the batch.
//
// Ten recovered routines from the `0x005c4000..=0x005c7fff` client/command
// helper region.  The area is dominated by GUI registration wrappers and
// debug-only accumulator code; only entries whose observable behaviour can
// be expressed with the existing [`crate::sim::World`] / [`crate::sim::SimUnit`]
// fields are translated here, and each item names the exact retail address
// it was recovered from.
//
// Helpers that agent09 already modelled as an alliance precondition
// (`FUN_005c8ad0`) are reported through an explicit `same_side` argument
// instead of being re-derived.  Unmodelled `CUnit` bytes are likewise
// supplied as caller arguments and called out in the item docs.

impl SimUnit {
    /// `0x005c78e0`: true when this unit's `CUnit+0x64` row is `0x7d` and the
    /// other unit's `CUnit+0x4c` owner byte is the same.  The recovered body
    /// reads the row through the type getter and compares the owner bytes
    /// directly, so no `units.dat` lookup is needed beyond the row constant.
    pub fn a17_type_7d_same_owner(&self, other: &SimUnit) -> bool {
        self.type_id == 0x7d && self.owner == other.owner
    }

    /// `0x005c7c20`: precondition for registering the `0x005c78e0`
    /// callback.  The recovered body requires the unit's row (`CUnit+0x64`)
    /// to be `0x7d` and `FUN_00695c10(0x7d, owner)` to return nonzero; only
    /// then does it insert the callback into the GUI list.  The GUI
    /// insertion is not modelled, so the data-table answer is supplied as
    /// `available`.
    pub fn a17_type_7d_available(&self, available: bool) -> bool {
        self.type_id == 0x7d && available
    }
}

impl World {
    /// `0x005c4e03`: debug guard that walks the unit list and fails when an
    /// entry's owner byte (`CUnit+0x4c`) equals `owner`.  The recovered body
    /// first compares the absolute coordinate delta with the map width
    /// (`DAT_00fa3728`) and only then scans the list; only the list predicate
    /// is observable in this model.
    ///
    /// Returns true when no entry of [`World::units`] belongs to `owner`
    /// (the retail success path).
    pub fn a17_owner_absent_from_units(&self, owner: u8) -> bool {
        !self.units.iter().any(|unit| unit.owner == owner)
    }

    /// `0x005c58b0`: walk the visible-unit list from its head
    /// (`DAT_00fa36a4`) through the `CUnit+0x04` next links and invoke a
    /// callback for each entry.  The retail pointer/functor object is
    /// represented by the Rust closure; list membership uses the same
    /// hidden predicate as the visible-list accessors (alive and not loaded
    /// into a transport or Bunker).
    pub fn a17_visit_visible_units<F: FnMut(u32)>(&self, mut visit: F) {
        for unit in self.units.iter().rev() {
            if unit.alive && unit.in_transport.is_none() && !unit.in_bunker {
                visit(unit.id);
            }
        }
    }

    /// `0x005c60b0`: worker/flag-target gate.  The recovered body applies
    /// every flag helper to its first unit argument: the worker row
    /// (`units.dat` flag `0x8`), `CUnit+0xdc` bit 0, the completed bit 4,
    /// bit 30 and the worker-only `CUnit+0xc0` linked target must all be in
    /// the idle-worker state.  It then rejects the case where the second
    /// argument is the owned `0xd7` Flag row, whose type comes from
    /// `CUnit+0x64`.
    ///
    /// `CUnit+0xdc` bits 0 and 30 are not separate [`SimUnit`] fields, so
    /// they are supplied by the caller.  Returns true on the retail success
    /// path.
    pub fn a17_worker_flag_target_gate(
        &self,
        worker: usize,
        other: usize,
        status_bit0: bool,
        status_bit30: bool,
    ) -> bool {
        let worker_unit = &self.units[worker];
        let other_unit = &self.units[other];
        self.data.unit(worker_unit.type_id).is_worker()
            && status_bit0
            && !worker_unit.completed
            && !status_bit30
            && worker_unit.linked_target().is_none()
            && !(other_unit.type_id == 0xd7 && other_unit.owner == worker_unit.owner)
    }

    /// `0x005c6210`: rectangle computation for a centred screen box.  The
    /// recovered body reads two 16-bit table extents, computes
    /// `-32 - extent / 2 + position` for each axis and then adds the extent
    /// plus `0x40` for the opposite corner.  Retail stores the four results
    /// as 16-bit words and hands them to the GUI list builder; only the
    /// arithmetic is translated here.
    ///
    /// `centre` is the unit position, `width`/`height` are the two extents
    /// read by the retail getters.
    pub fn a17_selection_rect(centre: (i32, i32), width: i32, height: i32) -> [i32; 4] {
        // The retail code uses an arithmetic shift, i.e. floor division.
        let x0 = centre.0 - 32 - (width >> 1);
        let y0 = centre.1 - 32 - (height >> 1);
        [x0, y0, x0 + width + 0x40, y0 + height + 0x40]
    }

    /// `0x005c72c0`: target gate for the fixed weapon row `0x39`.  The
    /// recovered body first calls the same-side helper `FUN_005c8ad0`
    /// (modelled as `same_side`), then requires `FUN_0059ca70(0x39, target)`
    /// to accept the first argument with the weapon belonging to the second.
    /// It rejects target heroes (`units.dat` flag `0x40`), and finally
    /// accepts when the force flag is set, when the target's whole-point HP
    /// plus shields is at least 100, when its row is a worker, when its row
    /// is one of `0x1e`, `5`, `0x22`, or when its current order byte lies in
    /// `0x7b..=0x81`.
    pub fn a17_ability_39_gate(
        &self,
        target: usize,
        caster: usize,
        same_side: bool,
        force_flag: bool,
    ) -> bool {
        if !same_side {
            return false;
        }
        let target_unit = &self.units[target];
        let caster_unit = &self.units[caster];
        let info = crate::data::WeaponTarget {
            unit: self.data.unit(target_unit.type_id),
            owner: target_unit.owner,
            flying: self.is_air_unit(target),
            untargetable: !target_unit.alive
                || target_unit.invincible
                || target_unit.status.stasis_ticks > 0,
        };
        if !self
            .data
            .weapon_target_ok(0x39, caster_unit.owner, Some(info))
        {
            return false;
        }
        if self.data.unit(target_unit.type_id).is_hero() {
            return false;
        }
        if force_flag || self.unit_current_total_points(target) >= 100 {
            return true;
        }
        if self.data.unit(target_unit.type_id).is_worker() {
            return true;
        }
        if matches!(target_unit.type_id, 0x1e | 5 | 0x22) {
            return true;
        }
        matches!(target_unit.order.order_id(), 0x7b..=0x81)
    }

    /// `0x005c7b60`: same-owner worker gate.  The recovered body requires
    /// equal `CUnit+0x4c` owners, the worker row (`units.dat` flag `0x8`),
    /// a clear Bunker bit (`CUnit+0xdc` bit 6), a non-null `CUnit+0x134`
    /// link, and a resolver call that returns the same unit.  Both
    /// `CUnit+0x134` and the resolver are unmodelled and are supplied by the
    /// caller as `has_link` / `resolves_to_self`.
    pub fn a17_worker_link_gate(
        &self,
        worker: usize,
        other: usize,
        has_link: bool,
        resolves_to_self: bool,
    ) -> bool {
        let worker_unit = &self.units[worker];
        worker_unit.owner == self.units[other].owner
            && self.data.unit(worker_unit.type_id).is_worker()
            && !worker_unit.in_bunker
            && has_link
            && resolves_to_self
    }

    /// `0x005c7a70`: conditional `0x400` registration wrapper.  A nonzero
    /// second argument short-circuits to zero; otherwise the recovered body
    /// calls the GUI registry and returns its pointer.  The registry call is
    /// represented by the `registered` argument.
    pub fn a17_register_400_when_unflagged(flag: bool, registered: Option<u32>) -> Option<u32> {
        if flag { None } else { registered }
    }

    /// `0x005c7f30`: registration class selection.  A nonzero second
    /// argument selects `0x120`; otherwise the per-player query
    /// `FUN_00635720(owner)` picks `0x800` when it is nonzero and `0x400`
    /// when it is zero.  The subsequent GUI list lookup and its
    /// `CUnit+0x5c` target unwrap are registry state and are not modelled.
    pub fn a17_registration_class(flag: bool, player_flag: bool) -> u16 {
        if flag {
            0x120
        } else if player_flag {
            0x800
        } else {
            0x400
        }
    }
}

#[cfg(test)]
mod tests_agent17 {
    use super::*;
    use crate::ids::unit as uid;
    use crate::sim::Order;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(crate::data::GameData::bundled().unwrap()),
            crate::map::Terrain::open(64, 64),
            2,
        )
    }

    /// `0x005c4e03`: the guard scans every unit entry, so a single unit of
    /// the queried owner makes the predicate false.
    #[test]
    fn owner_absence_follows_the_unit_list() {
        let mut w = world();
        assert!(w.a17_owner_absent_from_units(0));
        assert!(w.a17_owner_absent_from_units(1));

        w.spawn(0, uid::MARINE, 100, 100).unwrap();
        assert!(!w.a17_owner_absent_from_units(0));
        assert!(w.a17_owner_absent_from_units(1));

        w.spawn(1, uid::SCV, 200, 100).unwrap();
        assert!(!w.a17_owner_absent_from_units(0));
        assert!(!w.a17_owner_absent_from_units(1));
    }

    /// `0x005c58b0`: the visitor follows the visible list from head (newest
    /// live unit) to tail and skips loaded units.
    #[test]
    fn visible_visitor_orders_newest_first_and_skips_loaded_units() {
        let mut w = world();
        let first = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        let transport = w.spawn(0, uid::DROPSHIP, 200, 100).unwrap();
        let second = w.spawn(0, uid::MARINE, 300, 100).unwrap();

        let mut seen = Vec::new();
        w.a17_visit_visible_units(|id| seen.push(id));
        assert_eq!(
            seen,
            vec![w.units[second].id, w.units[transport].id, w.units[first].id]
        );

        w.units[second].in_transport = Some(w.units[transport].id);
        let mut seen = Vec::new();
        w.a17_visit_visible_units(|id| seen.push(id));
        assert_eq!(seen, vec![w.units[transport].id, w.units[first].id]);

        w.units[first].in_bunker = true;
        let mut seen = Vec::new();
        w.a17_visit_visible_units(|id| seen.push(id));
        assert_eq!(seen, vec![w.units[transport].id]);
    }

    /// `0x005c60b0`: every guard must hold, and the owned Flag row is the
    /// one target that is rejected on the success arm.
    #[test]
    fn worker_flag_target_gate_requires_the_idle_worker_state() {
        let mut w = world();
        let scv = w.spawn(0, uid::SCV, 100, 100).unwrap();
        let marine = w.spawn(0, uid::MARINE, 200, 100).unwrap();
        let enemy_marine = w.spawn(1, uid::MARINE, 300, 100).unwrap();
        let flag = w.spawn(0, 0xd7, 400, 100).unwrap();
        let enemy_flag = w.spawn(1, 0xd7, 500, 100).unwrap();

        w.units[scv].completed = false;
        assert!(w.a17_worker_flag_target_gate(scv, marine, true, false));
        assert!(!w.a17_worker_flag_target_gate(scv, flag, true, false));
        assert!(w.a17_worker_flag_target_gate(scv, enemy_flag, true, false));
        assert!(!w.a17_worker_flag_target_gate(scv, marine, false, false));
        assert!(!w.a17_worker_flag_target_gate(scv, marine, true, true));

        w.units[scv].completed = true;
        assert!(!w.a17_worker_flag_target_gate(scv, marine, true, false));
        w.units[scv].completed = false;

        w.units[scv].order = Order::Gather {
            resource: w.units[marine].id,
        };
        assert!(!w.a17_worker_flag_target_gate(scv, marine, true, false));

        assert!(!w.a17_worker_flag_target_gate(marine, enemy_marine, true, false));
    }

    /// `0x005c6210`: the origin is centre minus 32 minus half the extent and
    /// the opposite corner adds the extent plus 0x40.
    #[test]
    fn selection_rect_matches_the_recovered_arithmetic() {
        assert_eq!(
            World::a17_selection_rect((1000, 2000), 16, 20),
            [960, 1958, 1040, 2042]
        );
        assert_eq!(World::a17_selection_rect((0, 0), 15, 1), [-39, -32, 40, 33]);
        assert_eq!(
            World::a17_selection_rect((-100, -200), 18, 18),
            [-141, -241, -59, -159]
        );
    }

    /// `0x005c72c0`: same-side and the weapon predicate are hard gates;
    /// heroes are rejected, while the force flag / health / worker / row
    /// exceptions accept.
    #[test]
    fn ability_39_gate_follows_all_branches() {
        let mut w = world();
        let target = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        let caster = w.spawn(0, uid::MARINE, 200, 100).unwrap();

        assert!(!w.a17_ability_39_gate(target, caster, false, true));
        assert!(!w.a17_ability_39_gate(target, caster, true, false));
        assert!(w.a17_ability_39_gate(target, caster, true, true));

        w.units[target].hp = 100 << 8;
        assert!(w.a17_ability_39_gate(target, caster, true, false));

        w.units[target].hp = 40 << 8;
        let worker = w.spawn(0, uid::SCV, 300, 100).unwrap();
        assert!(w.a17_ability_39_gate(worker, caster, true, false));

        let hero_type = w
            .data
            .units
            .iter()
            .position(|unit| unit.is_hero())
            .expect("a hero row") as u16;
        let hero = w.spawn(0, hero_type, 400, 100).unwrap();
        assert!(!w.a17_ability_39_gate(hero, caster, true, true));

        let special = w.spawn(0, 0x1e, 500, 100).unwrap();
        assert!(!w.data.unit(0x1e).is_hero());
        assert!(w.a17_ability_39_gate(special, caster, true, false));
    }

    /// `0x005c78e0`: both the row check and the owner comparison are
    /// required.
    #[test]
    fn type_7d_gate_needs_the_row_and_the_owner() {
        let mut w = world();
        let a = w.spawn(0, 0x7d, 100, 100).unwrap();
        let b = w.spawn(0, 0x7d, 200, 100).unwrap();
        let c = w.spawn(1, 0x7d, 300, 100).unwrap();
        let marine = w.spawn(0, uid::MARINE, 400, 100).unwrap();

        assert!(w.units[a].a17_type_7d_same_owner(&w.units[b]));
        assert!(w.units[a].a17_type_7d_same_owner(&w.units[marine]));
        assert!(!w.units[a].a17_type_7d_same_owner(&w.units[c]));
        assert!(!w.units[marine].a17_type_7d_same_owner(&w.units[b]));
    }

    /// `0x005c7b60`: owner, worker row, Bunker bit and the two supplied
    /// link answers all participate.
    #[test]
    fn worker_link_gate_checks_owner_bunker_and_link() {
        let mut w = world();
        let scv = w.spawn(0, uid::SCV, 100, 100).unwrap();
        let marine = w.spawn(0, uid::MARINE, 200, 100).unwrap();
        let enemy = w.spawn(1, uid::MARINE, 300, 100).unwrap();

        assert!(!w.a17_worker_link_gate(scv, marine, false, true));
        assert!(!w.a17_worker_link_gate(scv, marine, true, false));
        assert!(w.a17_worker_link_gate(scv, marine, true, true));
        assert!(!w.a17_worker_link_gate(scv, enemy, true, true));
        assert!(!w.a17_worker_link_gate(marine, marine, true, true));

        w.units[scv].in_bunker = true;
        assert!(!w.a17_worker_link_gate(scv, marine, true, true));
    }

    /// `0x005c7f30`: the flag wins, otherwise the per-player query selects
    /// between the `0x400` and `0x800` classes.
    #[test]
    fn registration_class_follows_the_two_branch_flags() {
        assert_eq!(World::a17_registration_class(true, false), 0x120);
        assert_eq!(World::a17_registration_class(true, true), 0x120);
        assert_eq!(World::a17_registration_class(false, true), 0x800);
        assert_eq!(World::a17_registration_class(false, false), 0x400);
    }

    /// `0x005c7c20`: only the row `0x7d` and the data-table answer are
    /// visible in this model.
    #[test]
    fn type_7d_availability_gate_needs_the_row_and_the_table_answer() {
        let mut w = world();
        let unit = w.spawn(0, 0x7d, 100, 100).unwrap();
        let marine = w.spawn(0, uid::MARINE, 200, 100).unwrap();

        assert!(w.units[unit].a17_type_7d_available(true));
        assert!(!w.units[unit].a17_type_7d_available(false));
        assert!(!w.units[marine].a17_type_7d_available(true));
    }

    /// `0x005c7a70`: a set flag suppresses the registration result.
    #[test]
    fn registration_wrapper_short_circuits_on_the_flag() {
        assert_eq!(
            World::a17_register_400_when_unflagged(false, Some(7)),
            Some(7)
        );
        assert_eq!(World::a17_register_400_when_unflagged(true, Some(7)), None);
        assert_eq!(World::a17_register_400_when_unflagged(false, None), None);
    }
}

// ===========================================================================
// Merged from src/translated/agent24.rs
// ===========================================================================
// Translation batch 24.  Only this file is edited by the batch.
//
// `0x005a6000..=0x005a7fff` is the retail unit-sprite/overlay helper block.
// Every routine reconstructed below is a `decompiled_uncited` row from that
// range.  Retail reaches the sprite state through `CUnit+0x0c`, the `CSprite`
// object; [`crate::sim::SimUnit`] keeps no sprite objects, so the recovered
// sprite-local values (the state byte and the child-image lists) are explicit
// arguments or return values here, never new fields.  The `CUnit` fields the
// routines also read come from the existing public model: `owner`, `hp`,
// `type_id`, `mask_121` (`CUnit+0x121`), `visibility_mask` (`CUnit+0xe4`) and
// the `units.dat` flag word.
//
// Several ledger rows are shared entries in the middle of a larger retail
// routine (the sprite code calls them directly with registers already set);
// they are translated as the corresponding fragment and the surrounding
// routine is reconstructed separately.  Helper routines that were not
// recovered in this batch are described by role only, never by a claimed
// address.

/// Which sprite answered the child-image search of `0x005a6280`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A24OverlayOwner {
    /// The unit's own sprite (`CUnit+0x0c`).
    Unit,
    /// The addon's sprite, reached through the `CUnit+0x70` companion.
    Addon,
}

/// Route the sprite refresh of `0x005a64c0` takes after a type/addon change.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A24SpriteRoute {
    /// `units.dat` flag `0x20000000`: reset the sprite direction bits.
    ResetDirection,
    /// Ordinary sprite-state restore (the shared ordinary tail).
    Restore,
    /// Ordinary restore followed by the local player's Pylon-only update.
    PylonUpdate,
}

/// How `0x005a6530` applies the caller's overlay byte to the sprite.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A24OverlayApply {
    /// Image-only types clip the existing image and take the owner variant.
    Clip { image: u8, variant: u8 },
    /// Ordinary types set a new frame and the owner variant.
    Frame { image: u8, variant: u8, pylon: bool },
}

/// `0x005a6280`: search the unit's child-image list for an id in `lo..=hi`,
/// then (only when the unit has an addon) repeat the search on the addon's
/// list.  Retail makes the found child current by calling its image helper;
/// that operation is sprite-side, so the translated routine reports which
/// sprite owns the match.  `None` is the early return that leaves both sprites
/// untouched.  The caller passes the two child-id lists because the retail
/// lists live in the sprite object.
pub fn a24_overlay_child_owner(
    unit_images: &[u16],
    addon_images: Option<&[u16]>,
    lo: u16,
    hi: u16,
) -> Option<A24OverlayOwner> {
    let matches = |images: &[u16]| images.iter().any(|&id| lo <= id && id <= hi);
    if matches(unit_images) {
        return Some(A24OverlayOwner::Unit);
    }
    let addon_images = addon_images?;
    matches(addon_images).then_some(A24OverlayOwner::Addon)
}

/// `0x005a64a0`: convert the caller's overlay byte to the five-bit image slot
/// retail passes to its sprite image constructor:
/// `((value - 0x7c) >> 3) & 0x1f`.  The subtraction wraps, matching the exact
/// byte arithmetic of the retail code.
pub fn a24_overlay_index(value: u8) -> u8 {
    (value.wrapping_sub(0x7c) >> 3) & 0x1f
}

/// `0x005a65f0`: advance the sprite mirror/direction field (`bits 1-2`) down
/// one step modulo four.  Returns the new state and whether retail then asks
/// the image helper for the fallback image byte, which happens exactly when the
/// new direction field became zero.  A state whose field is already zero is
/// left alone.
pub fn a24_cycle_sprite_mirror(state: u8) -> (u8, bool) {
    let direction = state >> 1;
    if direction & 3 == 0 {
        return (state, false);
    }
    let updated = (((direction.wrapping_sub(1) << 1) ^ state) & 6) ^ state;
    (updated, (updated & 6) == 0)
}

/// `0x005a6600`: clear the sprite mirror/direction field.  `None` when the
/// field is already zero (retail returns early with zero); otherwise the
/// cleared state, which is also the branch where retail asks the image helper
/// for the fallback image byte and returns that byte instead.
pub fn a24_clear_sprite_mirror(state: u8) -> Option<u8> {
    if state & 6 == 0 {
        None
    } else {
        Some(state & !6)
    }
}

/// The shared image-state step behind [`World::a24_apply_owner_variant`]:
/// move the sprite mirror/direction field (`bits 1-2`) one step towards the
/// owner's colour variant.  Retail looks the variant up in the per-owner byte
/// table and then runs the image helper it shares with the two routines above:
/// the direction is advanced by one (`(dir + 1) & 3`) and, when the resulting
/// direction is 0 or 1 and no image is available, the direction bits are
/// cleared.  `owner_variant` is the raw table byte; the comparison is against
/// `owner_variant - 1` in full byte width, exactly as retail compares it.
pub fn a24_step_sprite_mirror(state: u8, owner_variant: u8, image_available: bool) -> u8 {
    let direction = (state >> 1) & 3;
    if direction == owner_variant.wrapping_sub(1) {
        return state;
    }
    let mut updated = ((state.wrapping_add(2) ^ state) & 6) ^ state;
    if (updated & 6) < 3 && !image_available {
        updated &= !6;
    }
    updated
}

/// `0x005a67c6`: build the 32-bit overlay flag word.  The CTF Flag row `0xd7`
/// with subtype byte `0x11` short-circuits to `0xff`.  Every other unit starts
/// from the `CUnit+0x121` mask, ORs the flag-table entry for owners `0..8`, and
/// ORs one entry per set `CUnit+0x121` bit (bits 0-11).  Retail indexes one
/// twelve-entry dword table (`0x00fc..0x0128` off the recovered data base) for
/// both the owner and the mask-bit lookups; the caller supplies that table.
pub fn a24_overlay_flag_word(
    type_id: u16,
    subtype_4d: u8,
    mask_121: u8,
    owner: u8,
    flags: &[u32; 12],
) -> u32 {
    if type_id == 0xd7 && subtype_4d == 0x11 {
        return 0xff;
    }
    let mut word = u32::from(mask_121);
    if owner < 8 {
        word |= flags[usize::from(owner)];
    }
    for (bit, &value) in flags.iter().enumerate() {
        if u32::from(mask_121) & (1u32 << bit) != 0 {
            word |= value;
        }
    }
    word
}

/// Which overlay code the builder of `0x005a6780` uses next.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A24OverlayCode {
    /// The Nuclear Missile row returns without an overlay.
    Return,
    /// The capability probe short-circuits the flag assembly with `0xff`.
    ShortCircuit(u8),
    /// Fall through to the `CUnit+0x121` mask/flag-table assembly.
    Assemble,
}

impl World {
    /// `0x005a61d0`: move a unit's damage-overlay frame towards the frame the
    /// current HP selects.  Retail stores the current frame in `CUnit+0xa7`
    /// and steps it one frame at a time, calling the sprite frame helper once
    /// per step.  The method returns the target frame and the number of
    /// one-frame sprite steps needed to reach it.
    ///
    /// With `m` the raw maximum HP (`0x00f8eab0[type]`), `t = m / 3` (the
    /// recovered max-HP-third lookup, [`World::unit_max_hp_third`]), `n =
    /// frame_count` and `span = (m - t) / n`, the target is
    /// `max(0, (hp - ((m - t) % span) - t - 1) / span)`, truncated to eight
    /// bits.  `frame_count` is the retail sprite byte plus one and is clamped
    /// to one here so the translated division is defined.
    pub fn a24_damage_overlay_transition(
        &self,
        unit_id: u32,
        frame_count: u8,
        current_frame: u8,
    ) -> Option<(u8, u32)> {
        let index = self.index_of(unit_id)?;
        let unit = &self.units[index];
        let max_hp = self.unit_max_hp_raw(unit.type_id);
        let third = max_hp / 3;
        let span = (max_hp - third) / i32::from(frame_count.max(1));
        let target = if span <= 0 {
            0
        } else {
            let remainder = (max_hp - third) % span;
            let value = (unit.hp - remainder - third - 1) / span;
            if value <= 0 { 0 } else { (value & 0xff) as u8 }
        };
        Some((target, u32::from(current_frame.abs_diff(target))))
    }

    /// `0x005a62c0`: choose the unit whose sprite receives an overlay image.
    /// Retail queries the `units.dat` subunit flag (`0x10`): a subunit row
    /// forwards the image to its parent at `CUnit+0x70` and records that parent
    /// in its 256-slot global table under the caller's byte.  Every other unit
    /// receives the image itself and does not touch the slot table.
    ///
    /// Returns the receiving unit id.  `None` is used for an unknown unit and
    /// for a subunit without a parent, the case retail would fault on when it
    /// dereferences the null `CUnit+0x70`.
    pub fn a24_register_subunit_overlay(
        &self,
        unit_id: u32,
        parent: Option<u32>,
        slot: u8,
        slots: &mut [Option<u32>; 256],
    ) -> Option<u32> {
        let index = self.index_of(unit_id)?;
        if self.data.unit(self.units[index].type_id).is_subunit() {
            let parent = parent?;
            slots[usize::from(slot)] = Some(parent);
            Some(parent)
        } else {
            Some(unit_id)
        }
    }

    /// `0x005a64c0` (the ordinary branch is the shared tail): route the
    /// sprite refresh after a type or addon change.  Types with `units.dat`
    /// flag `0x20000000` (image-only effect rows such as Disruption Web) take
    /// the reset path that clears the sprite direction bits and flag `0x08`.
    /// All other types restore the sprite state; when the game has not
    /// started, the unit belongs to the local player, its `CUnit+0xdc` bit 0
    /// is set (caller-supplied, not modelled) and the row is the Pylon `0x9c`,
    /// the Pylon-only update follows.
    pub fn a24_sprite_refresh_route(
        &self,
        unit_id: u32,
        game_started: bool,
        local_owner: u8,
        status_bit0: bool,
    ) -> Option<A24SpriteRoute> {
        let index = self.index_of(unit_id)?;
        let unit = &self.units[index];
        if self.data.unit(unit.type_id).flags & 0x2000_0000 != 0 {
            return Some(A24SpriteRoute::ResetDirection);
        }
        if !game_started
            && unit.owner == local_owner
            && status_bit0
            && unit.a01_pylon_update_required()
        {
            return Some(A24SpriteRoute::PylonUpdate);
        }
        Some(A24SpriteRoute::Restore)
    }

    /// `0x005a6530` (the ordinary branch is the `0x005a658f` tail): apply the
    /// caller's overlay byte to a unit's sprite.  Image-only types (flag
    /// `0x20000000`) clip the existing image, set the `0x08` sprite state bit
    /// and store the overlay byte.  Ordinary types set a new frame with the
    /// overlay byte and the owner variant, then run the same local-player
    /// Pylon tail as [`World::a24_sprite_refresh_route`].
    ///
    /// `owner_variant` is the per-owner byte retail reads from its colour table
    /// (`0x00f2acf8 + owner`); `overlay` is the caller's image/state byte.
    pub fn a24_overlay_apply(
        &self,
        unit_id: u32,
        overlay: u8,
        owner_variant: u8,
        game_started: bool,
        local_owner: u8,
        status_bit0: bool,
    ) -> Option<A24OverlayApply> {
        let index = self.index_of(unit_id)?;
        let unit = &self.units[index];
        if self.data.unit(unit.type_id).flags & 0x2000_0000 != 0 {
            return Some(A24OverlayApply::Clip {
                image: overlay,
                variant: owner_variant,
            });
        }
        let (image, variant, pylon) = self.a24_overlay_apply_frame(
            unit_id,
            overlay,
            owner_variant,
            game_started,
            local_owner,
            status_bit0,
        )?;
        Some(A24OverlayApply::Frame {
            image,
            variant,
            pylon,
        })
    }

    /// `0x005a658f`: the ordinary overlay branch as a directly callable entry.
    /// Retail jumps here from the sprite code that has already selected the
    /// unit, writes the frame/overlay byte and the owner variant to the sprite,
    /// and then runs the local-player Pylon tail.  The sprite write itself is
    /// not modelled, so the method reports the values that would be written
    /// plus whether the Pylon-only update follows.  `None` for an unknown unit.
    pub fn a24_overlay_apply_frame(
        &self,
        unit_id: u32,
        overlay: u8,
        owner_variant: u8,
        game_started: bool,
        local_owner: u8,
        status_bit0: bool,
    ) -> Option<(u8, u8, bool)> {
        let index = self.index_of(unit_id)?;
        let unit = &self.units[index];
        let pylon = !game_started
            && unit.owner == local_owner
            && status_bit0
            && unit.a01_pylon_update_required();
        Some((overlay, owner_variant, pylon))
    }

    /// `0x005a6610`: move a unit's sprite mirror/direction byte towards the
    /// owner's colour variant.  Retail skips a unit without a sprite and reads
    /// the variant from the per-owner byte table, so the caller supplies the
    /// table.  `None` means the unit is unknown or its owner has no table entry
    /// (retail's table is indexed by the raw owner byte).
    pub fn a24_apply_owner_variant(
        &self,
        unit_id: u32,
        state: u8,
        variants: &[u8],
        image_available: bool,
    ) -> Option<u8> {
        let index = self.index_of(unit_id)?;
        let variant = *variants.get(usize::from(self.units[index].owner))?;
        Some(a24_step_sprite_mirror(state, variant, image_available))
    }

    /// `0x005a6780`: status-overlay draw gate.  Retail returns before touching
    /// the sprite when the owner is outside `0..8` and the `CUnit+0x121` mask
    /// is empty, and for the Nuclear Missile row `0x0e`; everything else
    /// proceeds to the overlay builder.  `false` is that early return (also
    /// used for an unknown id).
    pub fn a24_overlay_draw_gate(&self, unit_id: u32) -> bool {
        let Some(index) = self.index_of(unit_id) else {
            return false;
        };
        let unit = &self.units[index];
        if unit.owner >= 8 && unit.mask_121() == 0 {
            return false;
        }
        unit.type_id != 0x0e
    }
}

impl SimUnit {
    /// `0x005a67a4`: overlay-code selection.  The Nuclear Missile row `0x0e`
    /// returns without a code.  A unit that passes the capability probe
    /// (passed in as `capable`) short-circuits the flag
    /// assembly with `0xff`; every other unit falls through to the
    /// `CUnit+0x121` mask/table assembly of [`a24_overlay_flag_word`].
    ///
    /// The ledger's decompiled body is a fragment entered in the middle of the
    /// builder with caller-owned registers, so it reads the shared draw tail as
    /// a non-returning helper.  The recovered instruction stream only branches
    /// to that tail, which is why the fall-through is kept as `Assemble`.
    pub fn a24_overlay_code(&self, capable: bool) -> A24OverlayCode {
        if self.type_id == 0x0e {
            return A24OverlayCode::Return;
        }
        if capable {
            return A24OverlayCode::ShortCircuit(0xff);
        }
        A24OverlayCode::Assemble
    }

    /// `0x005a6909`: the shared draw tail's cloak gate.  The ledger body is a
    /// fragment entered with caller-owned registers: `BL` carries the
    /// `CUnit+0xdc` cloak field (bits 8-9) that the draw wrapper read, and the
    /// tail applies the cloak offset/shimmer only when that field is non-zero
    /// and the unit is visible to the current player (`CUnit+0xe4` mask bit).
    /// [`SimUnit::cloak_state`] already holds that field, so the fragment is
    /// exposed as the gate itself; the image draw and the status-overlay
    /// update that follow are renderer-side and are not modelled here.
    pub fn a24_cloak_shimmer_visible(&self, viewer: u8) -> bool {
        self.cloak_state() != 0 && self.visibility_mask & (1u32 << (viewer & 31)) != 0
    }
}

#[cfg(test)]
mod tests_agent24 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use crate::sim::World;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World, owner: usize, type_id: u16) -> u32 {
        let slot = world.spawn(owner, type_id, 320, 320).expect("spawn");
        world.units[slot].id
    }

    fn slot_of(world: &World, id: u32) -> usize {
        world.index_of(id).expect("unit present")
    }

    #[test]
    fn damage_overlay_frame_follows_hp_third() {
        let mut w = world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        // Raw maximum HP 10240, one third 3413, three frames: span 2275,
        // remainder 2.  Full HP selects frame 2, medium HP frame 0.
        let i = slot_of(&w, marine);
        w.units[i].hp = 10240;
        assert_eq!(w.a24_damage_overlay_transition(marine, 3, 0), Some((2, 2)));
        assert_eq!(w.a24_damage_overlay_transition(marine, 3, 2), Some((2, 0)));
        assert_eq!(w.a24_damage_overlay_transition(marine, 3, 3), Some((2, 1)));

        w.units[i].hp = 7000;
        assert_eq!(w.a24_damage_overlay_transition(marine, 3, 0), Some((1, 1)));

        w.units[i].hp = 5120;
        assert_eq!(w.a24_damage_overlay_transition(marine, 3, 0), Some((0, 0)));

        w.units[i].hp = 1;
        assert_eq!(w.a24_damage_overlay_transition(marine, 3, 0), Some((0, 0)));

        // A zero frame count is clamped to one (retail always adds one), which
        // makes the whole HP range a single frame.
        w.units[i].hp = 10240;
        assert_eq!(w.a24_damage_overlay_transition(marine, 0, 0), Some((0, 0)));

        assert_eq!(w.a24_damage_overlay_transition(0xdead_beef, 3, 0), None);
    }

    #[test]
    fn child_owner_prefers_unit_then_addon() {
        let unit = [0x100u16, 0x17c, 0x180];
        assert_eq!(
            a24_overlay_child_owner(&unit, Some(&[0x17d]), 0x17c, 0x17e),
            Some(A24OverlayOwner::Unit)
        );
        assert_eq!(
            a24_overlay_child_owner(&unit, Some(&[0x17d]), 0x17d, 0x17e),
            Some(A24OverlayOwner::Addon)
        );
        assert_eq!(a24_overlay_child_owner(&unit, None, 0x17d, 0x17e), None);
        assert_eq!(
            a24_overlay_child_owner(&unit, Some(&[0x17f]), 0x17d, 0x17e),
            None
        );
        // An empty range matches nothing, exactly like the retail comparisons.
        assert_eq!(
            a24_overlay_child_owner(&unit, Some(&unit), 0x17e, 0x17d),
            None
        );
    }

    #[test]
    fn subunit_overlay_forwards_to_parent_and_fills_slot() {
        let mut w = world();
        let turret = spawn(&mut w, 0, uid::GOLIATH_TURRET);
        let marine = spawn(&mut w, 0, uid::MARINE);
        let parent = spawn(&mut w, 0, uid::GOLIATH);
        let mut slots = [None; 256];

        assert_eq!(
            w.a24_register_subunit_overlay(turret, Some(parent), 7, &mut slots),
            Some(parent)
        );
        assert_eq!(slots[7], Some(parent));
        assert!(w.data.unit(uid::GOLIATH_TURRET).is_subunit());

        assert_eq!(
            w.a24_register_subunit_overlay(marine, Some(parent), 9, &mut slots),
            Some(marine)
        );
        assert_eq!(slots[9], None, "ordinary units do not write the slot table");

        assert_eq!(
            w.a24_register_subunit_overlay(turret, None, 7, &mut slots),
            None
        );
        assert_eq!(
            w.a24_register_subunit_overlay(0xdead_beef, None, 0, &mut slots),
            None
        );
    }

    #[test]
    fn overlay_index_is_a_five_bit_slot() {
        assert_eq!(a24_overlay_index(0x7c), 0);
        assert_eq!(a24_overlay_index(0x84), 1);
        assert_eq!(a24_overlay_index(0x7b), 0x1f);
        assert_eq!(a24_overlay_index(0x7f), 0);
        assert_eq!(a24_overlay_index(0x80), 0);
        assert_eq!(a24_overlay_index(0xff), 0x10);
        // Every input stays inside the five-bit slot range.
        for value in 0..=255u8 {
            assert!(a24_overlay_index(value) < 32);
        }
    }

    #[test]
    fn sprite_refresh_route_uses_effect_flag_and_pylon_tail() {
        let mut w = world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        let effect = spawn(&mut w, 0, uid::DISRUPTION_WEB);
        let pylon = spawn(&mut w, 0, uid::PYLON);

        assert!(w.data.unit(uid::DISRUPTION_WEB).flags & 0x2000_0000 != 0);
        assert_eq!(
            w.a24_sprite_refresh_route(effect, false, 0, false),
            Some(A24SpriteRoute::ResetDirection)
        );
        assert_eq!(
            w.a24_sprite_refresh_route(marine, false, 0, true),
            Some(A24SpriteRoute::Restore)
        );
        assert_eq!(
            w.a24_sprite_refresh_route(pylon, false, 0, true),
            Some(A24SpriteRoute::PylonUpdate)
        );
        // Wrong owner or a started game drops the Pylon tail.
        assert_eq!(
            w.a24_sprite_refresh_route(pylon, false, 1, true),
            Some(A24SpriteRoute::Restore)
        );
        assert_eq!(
            w.a24_sprite_refresh_route(pylon, true, 0, true),
            Some(A24SpriteRoute::Restore)
        );
        // Status bit 0 is required for the Pylon update.
        assert_eq!(
            w.a24_sprite_refresh_route(pylon, false, 0, false),
            Some(A24SpriteRoute::Restore)
        );
        assert_eq!(
            w.a24_sprite_refresh_route(0xdead_beef, false, 0, true),
            None
        );
    }

    #[test]
    fn overlay_apply_selects_clip_or_frame() {
        let mut w = world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        let effect = spawn(&mut w, 0, uid::DISRUPTION_WEB);
        let pylon = spawn(&mut w, 0, uid::PYLON);

        assert_eq!(
            w.a24_overlay_apply(effect, 0x21, 3, false, 0, true),
            Some(A24OverlayApply::Clip {
                image: 0x21,
                variant: 3
            })
        );
        assert_eq!(
            w.a24_overlay_apply(marine, 0x21, 3, false, 0, true),
            Some(A24OverlayApply::Frame {
                image: 0x21,
                variant: 3,
                pylon: false
            })
        );
        assert_eq!(
            w.a24_overlay_apply(pylon, 0x21, 3, false, 0, true),
            Some(A24OverlayApply::Frame {
                image: 0x21,
                variant: 3,
                pylon: true
            })
        );
        assert_eq!(
            w.a24_overlay_apply(pylon, 0x21, 3, true, 0, true),
            Some(A24OverlayApply::Frame {
                image: 0x21,
                variant: 3,
                pylon: false
            })
        );
        assert_eq!(
            w.a24_overlay_apply(0xdead_beef, 0, 0, false, 0, false),
            None
        );
    }

    #[test]
    fn sprite_mirror_cycle_and_clear_match_byte_arithmetic() {
        // Direction 1 -> 0 and the fallback image byte is requested.
        assert_eq!(a24_cycle_sprite_mirror(0b0000_0010), (0, true));
        // Direction 2 -> 1, fallback not requested.
        assert_eq!(a24_cycle_sprite_mirror(0b0000_0100), (0b0000_0010, false));
        // Direction 3 -> 2.
        assert_eq!(a24_cycle_sprite_mirror(0b0000_0110), (0b0000_0100, false));
        // Unrelated state bits survive.
        assert_eq!(a24_cycle_sprite_mirror(0b1010_0010), (0b1010_0000, true));
        // Direction 0 is untouched.
        assert_eq!(a24_cycle_sprite_mirror(0b1010_0000), (0b1010_0000, false));
        assert_eq!(a24_cycle_sprite_mirror(0b1010_0001), (0b1010_0001, false));

        assert_eq!(a24_clear_sprite_mirror(0b0000_0110), Some(0b0000_0000));
        assert_eq!(a24_clear_sprite_mirror(0b1010_0110), Some(0b1010_0000));
        assert_eq!(a24_clear_sprite_mirror(0b1010_0001), None);
    }

    #[test]
    fn owner_variant_step_moves_one_direction() {
        // Variant 3 asks for direction 2; direction 1 steps to 2.
        assert_eq!(a24_step_sprite_mirror(0b0000_0010, 3, true), 0b0000_0100);
        // Same direction: untouched.
        assert_eq!(a24_step_sprite_mirror(0b0000_0100, 3, true), 0b0000_0100);
        // Variant 0 compares against 0xff in the retail byte width, so it
        // always takes a step; the resulting direction 0 clears when no image.
        assert_eq!(a24_step_sprite_mirror(0b0000_0110, 0, false), 0b0000_0000);
        // Direction 2 is not below 3, so the image flag does not clear it.
        assert_eq!(a24_step_sprite_mirror(0b0000_0010, 0, false), 0b0000_0100);
    }

    #[test]
    fn owner_variant_lookup_uses_unit_owner() {
        let mut w = world();
        let marine = spawn(&mut w, 1, uid::MARINE);
        let variants = [2u8, 3, 4];
        assert_eq!(
            w.a24_apply_owner_variant(marine, 0b0000_0010, &variants, true),
            Some(0b0000_0100)
        );
        assert_eq!(
            w.a24_apply_owner_variant(marine, 0b0000_0100, &variants, true),
            Some(0b0000_0100)
        );
        // No table entry for the owner: retail would index past its table.
        assert_eq!(
            w.a24_apply_owner_variant(marine, 0b0000_0010, &[2u8], true),
            None
        );
        assert_eq!(
            w.a24_apply_owner_variant(0xdead_beef, 0, &variants, true),
            None
        );
    }

    #[test]
    fn overlay_draw_gate_rejects_unknown_owner_and_nuke() {
        let mut w = world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        let nuke = spawn(&mut w, 0, uid::NUCLEAR_MISSILE);
        assert!(w.a24_overlay_draw_gate(marine));
        assert!(!w.a24_overlay_draw_gate(nuke));

        let i = slot_of(&w, marine);
        w.units[i].owner = 8;
        assert!(!w.a24_overlay_draw_gate(marine));
        w.units[i].set_mask_121_bit(0);
        assert!(w.a24_overlay_draw_gate(marine));
        assert!(!w.a24_overlay_draw_gate(0xdead_beef));
    }

    #[test]
    fn overlay_code_selects_return_short_circuit_or_assembly() {
        let mut w = world();
        let nuke = spawn(&mut w, 0, uid::NUCLEAR_MISSILE);
        let marine = spawn(&mut w, 0, uid::MARINE);
        let nuke_idx = slot_of(&w, nuke);
        let marine_idx = slot_of(&w, marine);
        assert_eq!(
            w.units[nuke_idx].a24_overlay_code(false),
            A24OverlayCode::Return
        );
        assert_eq!(
            w.units[marine_idx].a24_overlay_code(true),
            A24OverlayCode::ShortCircuit(0xff)
        );
        assert_eq!(
            w.units[marine_idx].a24_overlay_code(false),
            A24OverlayCode::Assemble
        );
    }

    #[test]
    fn overlay_frame_entry_reports_pylon_tail() {
        let mut w = world();
        let marine = spawn(&mut w, 0, uid::MARINE);
        let pylon = spawn(&mut w, 0, uid::PYLON);
        assert_eq!(
            w.a24_overlay_apply_frame(marine, 0x21, 3, false, 0, true),
            Some((0x21, 3, false))
        );
        assert_eq!(
            w.a24_overlay_apply_frame(pylon, 0x21, 3, false, 0, true),
            Some((0x21, 3, true))
        );
        assert_eq!(
            w.a24_overlay_apply_frame(pylon, 0x21, 3, true, 0, true),
            Some((0x21, 3, false))
        );
        assert_eq!(
            w.a24_overlay_apply_frame(0xdead_beef, 0x21, 3, false, 0, true),
            None
        );
    }

    #[test]
    fn cloak_shimmer_needs_a_cloaked_visible_unit() {
        let mut w = world();
        let ghost = spawn(&mut w, 0, uid::GHOST);
        let i = slot_of(&w, ghost);
        // Uncloaked units take the plain draw path.
        assert!(!w.units[i].a24_cloak_shimmer_visible(0));
        w.units[i].status.cloaked = true;
        w.units[i].visibility_mask = u32::MAX;
        assert!(w.units[i].a24_cloak_shimmer_visible(0));
        w.units[i].visibility_mask = 0;
        assert!(!w.units[i].a24_cloak_shimmer_visible(0));
        w.units[i].visibility_mask = 1;
        assert!(w.units[i].a24_cloak_shimmer_visible(0));
        assert!(!w.units[i].a24_cloak_shimmer_visible(1));
    }

    #[test]
    fn overlay_flag_word_ors_owner_and_mask_entries() {
        let mut table = [0u32; 12];
        for (i, value) in table.iter_mut().enumerate() {
            *value = 0x100 + i as u32;
        }

        // Unknown-owner path: only the mask bits contribute.
        assert_eq!(
            a24_overlay_flag_word(uid::MARINE, 0, 0b0000_1001, 9, &table),
            0b1001 | 0x100 | 0x103
        );
        // Owner 2 adds its entry.
        assert_eq!(
            a24_overlay_flag_word(uid::MARINE, 0, 0b0000_1001, 2, &table),
            0b1001 | 0x100 | 0x103 | 0x102
        );
        // Empty mask and owner 9 keep the word at zero.
        assert_eq!(a24_overlay_flag_word(uid::MARINE, 0, 0, 9, &table), 0);
        // The CTF Flag row with subtype 0x11 short-circuits to 0xff.
        assert_eq!(a24_overlay_flag_word(0xd7, 0x11, 0b1, 0, &table), 0xff);
        assert_eq!(
            a24_overlay_flag_word(0xd7, 0x12, 0b1, 0, &table),
            0b1 | 0x100
        );
    }
}

// ===========================================================================
// Merged from src/translated/agent25.rs
// ===========================================================================
// Translation batch 25.  Only this file is edited by the batch.
//
// Batch 25 owns `0x005a8000..=0x005a9fff`.  The ledger lists twelve rows in
// that window: nine `decompiled_uncited` entries and three
// `decompile_failed` entries whose cached bodies are empty.  All nine
// uncited entries are translated below, and the three failed entries were
// recovered from the shipped runtime image's disassembly (the cached `.c`
// files contain only the size header).
//
// Every routine in this window belongs to the executable's self-decrypting
// loader / anti-tamper stub, not to game logic.  The region is built from
// overlapping-instruction decoys and encrypted gaps, so the decompiler
// truncates most bodies with `halt_baddata()`; the coherent blocks that do
// survive are straight-line "operator ladders" (a four-way selector that
// picks add / subtract / xor / constant), bit rotations, 16-bit half-word
// folds and `rdtsc`/noreturn-abort tails.  None of them reads or writes the
// simulation's `World` or `CUnit` state, and retail never returns from the
// ones that end in the abort helper.
//
// Consequently the translations reproduce the recovered arithmetic as
// deterministic helpers attached to [`World`] (the inherent-method namespace
// used by the batch convention) and never add persistent state.  Each doc
// comment names the exact address, the ledger status and the recovered C /
// disassembly shape; no other routine's address is cited.

/// `0x005a8466`: low 16 bits of the embedded constant `0x5a496a08`, loaded
/// into the loader's first state word `A`.
pub const A25_LOADER_SEED: u32 = 0x6a08;

/// `0x005a8466`: the `imul ...,0x25` factor that derives both the rotate
/// count and the dispatch selector from the round counter.
pub const A25_LOADER_ROUND_STEP: u32 = 0x25;

/// `0x005a8fdf`: the increment applied to the watched 32-bit counter.
pub const A25_INTEGRITY_STEP: u32 = 0x3b_743;

/// `0x005a8fdf`: pre-increment value from which the addition wraps the
/// counter to zero (`0xfffc48bd + 0x3b743 == 0x1_0000_0000`).
pub const A25_INTEGRITY_WRAP_AT: u32 = 0xfffc_48bd;

/// The repeated four-way ladder: `op` 0 adds, 1 subtracts, 2 xors and every
/// other value keeps `lhs`.  Recovered from the forward blocks of
/// `0x005a903a`, which reuse the same compare ladder with register operands.
fn a25_pick(op: u32, lhs: u32, rhs: u32) -> u32 {
    match op {
        0 => lhs.wrapping_add(rhs),
        1 => lhs.wrapping_sub(rhs),
        2 => lhs ^ rhs,
        _ => lhs,
    }
}

/// The inverse ordering used by the second half of each ladder pair
/// (`0x005a903a`) and by the accumulator ladder that opens `0x005a98c0`:
/// `op` 0 subtracts, 1 adds, 2 xors, other keeps `lhs`.
fn a25_pick_inv(op: u32, lhs: u32, rhs: u32) -> u32 {
    match op {
        0 => lhs.wrapping_sub(rhs),
        1 => lhs.wrapping_add(rhs),
        2 => lhs ^ rhs,
        _ => lhs,
    }
}

/// The constant-first ladder (`0x005a8c02`, and the `800`/`0x18`/`900`/`100`
/// blocks of `0x005a903a`): `op` 0 returns `value + constant`, 1 returns
/// `constant - value`, 2 xors, and every other value returns the constant.
fn a25_pick_const(op: u32, value: u32, constant: u32) -> u32 {
    match op {
        0 => value.wrapping_add(constant),
        1 => constant.wrapping_sub(value),
        2 => value ^ constant,
        _ => constant,
    }
}

/// The identity/add/xor ladder that opens `0x005a98c0`: `op` 0 keeps `lhs`,
/// 1 adds, 2 xors and other values keep `lhs`.
fn a25_pick_identity(op: u32, lhs: u32, rhs: u32) -> u32 {
    match op {
        0 => lhs,
        1 => lhs.wrapping_add(rhs),
        2 => lhs ^ rhs,
        _ => lhs,
    }
}

impl World {
    /// `0x005a8175` (`FUN_005a8175`, 3 bytes, `decompiled_uncited`).
    ///
    /// The whole body is `jmp dword ptr [edi+ecx]`:
    ///
    /// ```c
    /// (**(code **)(unaff_EDI + in_ECX))();
    /// ```
    ///
    /// The routine is the loader's indexed dispatch thunk: the two registers
    /// are added to form a byte offset into a table of code pointers and the
    /// selected pointer is entered.  [`Self::a25_dispatch_slot`] reproduces the
    /// address formation with bounds and 4-byte alignment checks; a misaligned
    /// or out-of-range slot is the case retail would fault on, reported as
    /// `None` instead of an invalid call.  The thunk touches no world state.
    pub fn a25_dispatch_slot(&self, table: &[u32], byte_offset: u32) -> Option<u32> {
        let offset = byte_offset as usize;
        if !offset.is_multiple_of(4) {
            return None;
        }
        table.get(offset / 4).copied()
    }

    /// `0x005a8466` (`FUN_005a8466`, 232 bytes, ledger `decompile_failed`;
    /// recovered from the shipped runtime image's disassembly).
    ///
    /// The routine prepares one loader round.  The recovered instructions are:
    ///
    /// ```text
    /// 0x005a84c6  [ebp-0x9e0] = 0x5a496a08        ; constant, low word used
    /// 0x005a84d0  A           = movzx word [...]
    /// 0x005a84dd  round       = 2
    /// 0x005a84f3  lo          = word [state]
    /// 0x005a8506  hi          = state >> 16
    /// 0x005a851b  scaled      = round * 0x25
    /// 0x005a853a  selector    = (scaled + round) & 7
    /// 0x005a853c  compare selector with 3, jump to the combine switch above 3
    /// ```
    ///
    /// The four rotate blocks reached through the `0x005ab940` table use
    /// `rotate = ((scaled + round) & 0xf) + 1`.  Returns `(selector, rotate)`.
    /// The `A` word is [`A25_LOADER_SEED`]; the combine keys are the high and
    /// low 16-bit halves of the previous state word, which the caller supplies
    /// to [`Self::a25_loader_combine`].
    pub fn a25_loader_round_selector(&self, round: u32) -> (u32, u32) {
        let scaled = round.wrapping_mul(A25_LOADER_ROUND_STEP);
        let sum = scaled.wrapping_add(round);
        (sum & 7, (sum & 0xf) + 1)
    }

    /// `0x005a85c4` (`FUN_005a85c4`, 892 bytes, ledger `decompile_failed`;
    /// recovered from the shipped runtime image's disassembly).
    ///
    /// The entry is the eight-way combine switch whose jump table sits at
    /// `0x005ab950` (targets `0x005a862c`, `0x005a85d6`, `0x005a85de`,
    /// `0x005a85e6`, `0x005a85f5`, `0x005a8604`, `0x005a8614`,
    /// `0x005a8620`).  With `a = [ebp-0x7c]` and `b = [ebp-0x80]` the cases
    /// are exactly:
    ///
    /// | index | recovered body      |
    /// |-------|---------------------|
    /// | 0     | `a + b`             |
    /// | 1     | `a - b`             |
    /// | 2     | `a ^ b`             |
    /// | 3     | `a + (a - b)`       |
    /// | 4     | `b + (b - a)`       |
    /// | 5     | `b - a`             |
    /// | 6     | `b ^ !a`            |
    /// | 7     | `a ^ !b`            |
    /// | other | `a + b` (the `ja` target is the case-0 block) |
    ///
    /// Indices 6 and 7 are algebraically the same value because
    /// `(!a) ^ b == a ^ (!b)`; retail still keeps two separate blocks.
    /// After the switch the routine folds the result with the previous
    /// state's high half and rebuilds the word as
    /// `(result << 16) | state_low`, which is the caller's step and not part
    /// of this helper.  All arithmetic is 32-bit wrapping.
    pub fn a25_loader_combine(&self, mode: u32, a: u32, b: u32) -> u32 {
        match mode {
            0 => a.wrapping_add(b),
            1 => a.wrapping_sub(b),
            2 => a ^ b,
            3 => a.wrapping_add(a.wrapping_sub(b)),
            4 => b.wrapping_add(b.wrapping_sub(a)),
            5 => b.wrapping_sub(a),
            6 => b ^ !a,
            7 => a ^ !b,
            _ => a.wrapping_add(b),
        }
    }

    /// `0x005a8c02` (`FUN_005a8c02`, 525 bytes, ledger `decompile_failed`;
    /// recovered from the shipped runtime image's disassembly).
    ///
    /// The recovered head is the constant-`4` ladder on the operation index
    /// `[ebp+0x14]` and the value in `EDX`:
    ///
    /// ```c
    /// if (op == 0)      value = value + 4;
    /// else if (op == 1) value = 4 - value;
    /// else if (op == 2) value = value ^ 4;
    /// else              value = 4;
    /// ```
    ///
    /// The remainder of the body repeats the same add/sub/xor ladders with the
    /// `EBX`, `ESI` and `EDI` operands and folds the result into the loader
    /// state word; only the fully recovered head is reproduced here.
    pub fn a25_relative_add4(&self, op: u32, value: u32) -> u32 {
        a25_pick_const(op, value, 4)
    }

    /// `0x005a8fdf` (`FUN_005a8fdf`, 15 bytes, `decompiled_uncited`).
    ///
    /// The coherent body is the loader's timer/overflow gate.  The decompiled
    /// control flow is:
    ///
    /// ```c
    /// uVar2 = *counter;              // value before the increment
    /// *counter = *counter + 0x3b743; // wraps exactly at 0xfffc48bd
    /// if (uVar2 < 0xfffc48bd)
    ///     flag = (klass == 5 && count > 1);
    /// else
    ///     flag = 1;
    /// ```
    ///
    /// `0xfffc48bd + 0x3b743 == 0x1_0000_0000`, so the compare is the carry
    /// flag of the increment: `pre_add >= 0xfffc48bd` means the counter wrapped.
    /// The second clause is the recovered `[ebp-0x3b8] == 5 && [ebp-0x3bc] > 1`
    /// test.  Returns the flag byte written to `[ebp-0x109]`; `true` is the
    /// branch that falls into the tamper-report chain at `0x005a903a`.
    pub fn a25_counter_wrap_gate(&self, pre_add: u32, klass: u32, count: u32) -> bool {
        pre_add >= A25_INTEGRITY_WRAP_AT || (klass == 5 && count > 1)
    }

    /// `0x005a903a` (`FUN_005a903a`, 245 bytes, `decompiled_uncited`).
    ///
    /// This is the gate-true branch: the loader builds an argument from six
    /// ladder steps.  With `op_first = [ebp+0x14]`, `op_pair = [ebp+0x1c]`
    /// (reused for `[ebp+0x24]`), `seed = [ebp+0x18]`, `X = [ebp+0x20]` and
    /// `Y = [ebp+0x28]` the decompiled C is:
    ///
    /// 1. `const` ladder with constant `800`: 0 `seed+800`, 1 `800-seed`,
    ///    2 `seed^800`, other `800`;
    /// 2. `op_pair` add/sub/xor with `X`;
    /// 3. `op_pair` add/sub/xor with `Y`;
    /// 4. inverse `op_pair` with `Y`;
    /// 5. inverse `op_pair` with `X`;
    /// 6. inverse `op_first` with `seed`.
    ///
    /// Every operation is paired with its inverse, so the chain always yields
    /// the obfuscated constant `800` regardless of the selectors or operands.
    /// After this the routine indexes a table with the result, calls through
    /// `FUN_00c86d80`, and continues with `0x18`, `900` and `100` versions of
    /// the same chain before `FUN_00c874a0` and the noreturn abort; only the
    /// fully recovered chain is reproduced.
    pub fn a25_tamper_branch_value(
        &self,
        op_first: u32,
        op_pair: u32,
        seed: u32,
        first: u32,
        second: u32,
    ) -> u32 {
        let mut value = a25_pick_const(op_first, seed, 800);
        value = a25_pick(op_pair, value, first);
        value = a25_pick(op_pair, value, second);
        value = a25_pick_inv(op_pair, value, second);
        value = a25_pick_inv(op_pair, value, first);
        a25_pick_inv(op_first, value, seed)
    }

    /// `0x005a954e` (`FUN_005a954e`, 10 bytes, `decompiled_uncited`).
    ///
    /// The cached body is the 32-bit counter decrement followed by the bad
    /// instruction that truncates control flow:
    ///
    /// ```c
    /// *(int *)(unaff_EBX + -0x7a74e38b) += -1;
    /// halt_baddata();          // no continuation
    /// ```
    ///
    /// The helper applies the wrapping decrement and reports `None` for the
    /// trap, so callers can observe the decremented counter without modelling
    /// a return that retail never performs.
    pub fn a25_decrement_and_trap(&self, counter: &mut i32) -> Option<i32> {
        *counter = counter.wrapping_sub(1);
        None
    }

    /// `0x005a98c0` (`FUN_005a98c0`, 1061 bytes, `decompiled_uncited`).
    ///
    /// The recovered head folds an incoming pair and the loader key:
    ///
    /// ```c
    /// // unaff_ESI is the selector: 1 adds, 2 xors, 0/other keeps EAX.
    /// v = select(eax, edx);
    /// // [ebp+0x14] is the operation: 0 subtracts, 1 adds, 2 xors,
    /// // every other value keeps the accumulator.
    /// v = op(v, in_ECX);
    /// ```
    ///
    /// The result is stored as the argument at `[ebp-0x29c]`; the rest of the
    /// routine builds the sibling abort arguments from the `900`, `[ebp+0x20]`
    /// and `[ebp+0x28]` ladders and finishes in `FUN_00c874a0` plus the
    /// noreturn abort.  Only the two fully recovered ladders are reproduced.
    pub fn a25_loader_state_fold(&self, select: u32, op: u32, lhs: u32, rhs: u32, key: u32) -> u32 {
        let folded = a25_pick_identity(select, lhs, rhs);
        a25_pick_inv(op, folded, key)
    }

    /// `0x005a9d80` (`FUN_005a9d80`, 756 bytes, `decompiled_uncited`).
    ///
    /// The recovered prologue is four instructions:
    ///
    /// ```text
    /// 0x005a9d81  ecx = [ebp-0x198]
    /// 0x005a9d87  eax = eax + ecx
    /// 0x005a9d89  ecx = [ebp-0x29c]
    /// 0x005a9d8f  ecx = ecx + eax
    /// 0x005a9d91  [ebp-0x29c] = ecx
    /// ```
    ///
    /// Returns `(seed + addend, accumulator + seed + addend)`: the first value
    /// is the updated `EAX`, the second the updated accumulator.  The remainder
    /// of the routine is an encrypted gap followed by `rdtsc` and repeated
    /// ladder chains, so only the recovered prologue is reproduced.
    pub fn a25_loader_accumulate(&self, seed: u32, addend: u32, accumulator: u32) -> (u32, u32) {
        let sum = seed.wrapping_add(addend);
        (sum, accumulator.wrapping_add(sum))
    }
}

impl crate::sim::SimUnit {
    /// `0x005a85ab` (`FUN_005a85ab`, 1 byte), `0x005a87b6`
    /// (`FUN_005a87b6`, 1 byte) and `0x005a9d4c` (`FUN_005a9d4c`, 15 bytes)
    /// are byte-identical `halt_baddata()` stubs in the ledger: the cached
    /// bodies contain only the truncation warning, and the bytes at each entry
    /// are an overlapping-instruction decoy (`0x90 0xfe 0xff`, `0xff 0xff`,
    /// and the tail of an overlapping `test`).  Retail has no continuation.
    ///
    /// One method cites all three because the recovered body is identical;
    /// `None` is the "no return" result.  It only borrows the unit so the
    /// caller can keep using it, mirroring the retail `ECX`-only entry.
    pub fn a25_bad_instruction_trap(&self) -> Option<()> {
        None
    }
}

#[cfg(test)]
mod tests_agent25 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use crate::sim::World;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    #[test]
    fn dispatch_slot_walks_the_recovered_indirect_jump() {
        // 0x005a8175
        let w = world();
        let table = [0xdead_beef, 0x1234_5678, 0xcafe_babe];
        assert_eq!(w.a25_dispatch_slot(&table, 0), Some(0xdead_beef));
        assert_eq!(w.a25_dispatch_slot(&table, 4), Some(0x1234_5678));
        assert_eq!(w.a25_dispatch_slot(&table, 8), Some(0xcafe_babe));
        assert_eq!(w.a25_dispatch_slot(&table, 12), None);
        assert_eq!(w.a25_dispatch_slot(&table, 2), None);
        assert_eq!(w.a25_dispatch_slot(&[], 0), None);
    }

    #[test]
    fn loader_round_selector_matches_the_recovered_arithmetic() {
        // 0x005a8466
        let w = world();
        assert_eq!(w.a25_loader_round_selector(0), (0, 1));
        assert_eq!(w.a25_loader_round_selector(2), (4, 13));
        assert_eq!(w.a25_loader_round_selector(3), (2, 3));
        assert_eq!(w.a25_loader_round_selector(8), (0, 1));
        for round in 0..64u32 {
            let sum = round * A25_LOADER_ROUND_STEP + round;
            assert_eq!(
                w.a25_loader_round_selector(round),
                (sum & 7, (sum & 0xf) + 1),
                "round {round}"
            );
        }
        assert_eq!(A25_LOADER_SEED, 0x5a49_6a08u32 & 0xffff);
        assert_eq!(0x5a49_6a08u32 >> 16, 0x5a49);
    }

    #[test]
    fn loader_combine_matches_all_eight_jump_table_cases() {
        // 0x005a85c4
        let w = world();
        let a = 0x1234_5678u32;
        let b = 0x0fed_cba9u32;
        assert_eq!(w.a25_loader_combine(0, a, b), 0x2222_2221);
        assert_eq!(w.a25_loader_combine(1, a, b), 0x0246_8acf);
        assert_eq!(w.a25_loader_combine(2, a, b), 0x1dd9_9dd1);
        assert_eq!(w.a25_loader_combine(3, a, b), 0x147a_e147);
        assert_eq!(w.a25_loader_combine(4, a, b), 0x0da7_40da);
        assert_eq!(w.a25_loader_combine(5, a, b), 0xfdb9_7531);
        // Cases 6 and 7 are two blocks with the same algebra: b ^ !a == a ^ !b.
        assert_eq!(w.a25_loader_combine(6, a, b), 0xe226_622e);
        assert_eq!(w.a25_loader_combine(7, a, b), 0xe226_622e);
        assert_eq!(w.a25_loader_combine(8, a, b), 0x2222_2221);
        assert_eq!(w.a25_loader_combine(u32::MAX, 5, 7), 12);
    }

    #[test]
    fn relative_add4_matches_the_constant_ladder() {
        // 0x005a8c02
        let w = world();
        assert_eq!(w.a25_relative_add4(0, 0x1234), 0x1238);
        assert_eq!(w.a25_relative_add4(1, 0x1234), -0x1230i32 as u32);
        assert_eq!(w.a25_relative_add4(2, 0x1234), 0x1230);
        assert_eq!(w.a25_relative_add4(3, 0x1234), 4);
        assert_eq!(w.a25_relative_add4(u32::MAX, 0), 4);
        assert_eq!(w.a25_relative_add4(1, 0), 4);
    }

    #[test]
    fn counter_wrap_gate_detects_the_wrapping_addition() {
        // 0x005a8fdf
        let w = world();
        assert_eq!(A25_INTEGRITY_STEP, 0x3b_743);
        assert_eq!(A25_INTEGRITY_WRAP_AT, 0xfffc_48bd);
        assert_eq!(A25_INTEGRITY_WRAP_AT.wrapping_add(A25_INTEGRITY_STEP), 0);
        assert!(!w.a25_counter_wrap_gate(0xfffc_48bc, 0, 0));
        assert!(!w.a25_counter_wrap_gate(0xfffc_48bc, 5, 1));
        assert!(w.a25_counter_wrap_gate(0xfffc_48bc, 5, 2));
        assert!(w.a25_counter_wrap_gate(0xfffc_48bd, 0, 0));
        assert!(w.a25_counter_wrap_gate(u32::MAX, 0, 0));
        assert!(w.a25_counter_wrap_gate(0, 5, 2));
        assert!(!w.a25_counter_wrap_gate(0, 4, 100));
    }

    #[test]
    fn tamper_branch_chain_collapses_to_the_obfuscated_constant() {
        // 0x005a903a: each ladder step is paired with its inverse, so every
        // selector and operand combination yields 800 (0x320).
        let w = world();
        for op_first in 0..5u32 {
            for op_pair in 0..5u32 {
                for &(seed, first, second) in &[
                    (0u32, 0u32, 0u32),
                    (0x1122_3344, 0x5566_7788, 0x99aa_bbcc),
                    (u32::MAX, 1, 2),
                ] {
                    assert_eq!(
                        w.a25_tamper_branch_value(op_first, op_pair, seed, first, second),
                        800,
                        "first {op_first} pair {op_pair}"
                    );
                }
            }
        }
    }

    #[test]
    fn decrement_and_trap_reports_the_decremented_counter() {
        // 0x005a954e
        let w = world();
        let mut counter = 5;
        assert_eq!(w.a25_decrement_and_trap(&mut counter), None);
        assert_eq!(counter, 4);
        counter = 0;
        assert_eq!(w.a25_decrement_and_trap(&mut counter), None);
        assert_eq!(counter, -1);
        counter = i32::MIN;
        assert_eq!(w.a25_decrement_and_trap(&mut counter), None);
        assert_eq!(counter, i32::MAX);
    }

    #[test]
    fn loader_state_fold_matches_the_two_ladders() {
        // 0x005a98c0
        let w = world();
        // select 0 keeps lhs, select 1 adds, select 2 xors.
        assert_eq!(w.a25_loader_state_fold(0, 1, 0x1000, 0x234, 0x0f0f), 0x1f0f);
        assert_eq!(w.a25_loader_state_fold(1, 1, 0x1000, 0x234, 0x0f0f), 0x2143);
        assert_eq!(w.a25_loader_state_fold(2, 1, 0x1000, 0x234, 0x0f0f), 0x2143);
        // op 0 subtracts, op 1 adds, op 2 xors, other keeps the accumulator.
        assert_eq!(w.a25_loader_state_fold(1, 0, 0x1000, 0x234, 0x0f0f), 0x0325);
        assert_eq!(w.a25_loader_state_fold(1, 2, 0x1000, 0x234, 0xffff), 0xedcb);
        assert_eq!(w.a25_loader_state_fold(1, 9, 0x1000, 0x234, 0x0f0f), 0x1234);
        // 0x1234 - 0x0f0f == 0x0325 and 0x1234 ^ 0xffff == 0xedcb hold above.
        assert_eq!(w.a25_loader_state_fold(1, 0, 0, 0, 1), u32::MAX);
    }

    #[test]
    fn loader_accumulate_adds_seed_then_the_accumulator() {
        // 0x005a9d80
        let w = world();
        assert_eq!(w.a25_loader_accumulate(0x10, 0x20, 0x30), (0x30, 0x60));
        assert_eq!(w.a25_loader_accumulate(u32::MAX, 2, 0x40), (1, 0x41));
        assert_eq!(w.a25_loader_accumulate(0, 0, 0), (0, 0));
    }

    #[test]
    fn bad_instruction_stubs_never_continue() {
        // 0x005a85ab, 0x005a87b6, 0x005a9d4c
        let mut w = world();
        let index = w.spawn(0, uid::MARINE, 512, 512).unwrap();
        assert_eq!(w.units[index].a25_bad_instruction_trap(), None);
        assert!(w.units[index].a25_bad_instruction_trap().is_none());
    }

    #[test]
    fn loader_helpers_leave_the_world_untouched() {
        let mut w = world();
        let index = w.spawn(0, uid::MARINE, 512, 512).unwrap();
        let before = (
            w.units.len(),
            w.tick,
            w.units[index].id,
            w.units[index].hp,
            w.units[index].x,
            w.units[index].y,
        );
        let table = [1u32, 2, 3];
        let mut counter = 1;
        let _ = w.a25_dispatch_slot(&table, 4);
        let _ = w.a25_loader_round_selector(7);
        let _ = w.a25_loader_combine(6, 0x1234, 0x5678);
        let _ = w.a25_relative_add4(2, 0x99);
        let _ = w.a25_counter_wrap_gate(0xfffc_48bd, 5, 2);
        let _ = w.a25_tamper_branch_value(2, 0, 1, 2, 3);
        let _ = w.a25_decrement_and_trap(&mut counter);
        let _ = w.a25_loader_state_fold(2, 1, 3, 4, 5);
        let _ = w.a25_loader_accumulate(1, 2, 3);
        assert_eq!(
            (
                w.units.len(),
                w.tick,
                w.units[index].id,
                w.units[index].hp,
                w.units[index].x,
                w.units[index].y,
            ),
            before
        );
        assert_eq!(counter, 0);
    }
}

// ===========================================================================
// Merged from src/translated/agent26.rs
// ===========================================================================
// Translation batch 26.  Only this file is edited by the batch.
//
// Coverage: the `decompiled_uncited` rows of `0x005aa000..=0x005abfff`.
//
// The window belongs to the classic client's briefing / dialog layer.  Most
// of its ledger rows are *not* function entries: retail keeps inline
// `switch` jump tables in this region, so the recorded addresses land either
// inside an instruction or inside the table itself.  Every translation below
// names the exact address, states what the bytes at that address do and
// which fields of the dialog object the arm writes.  That object is not a
// `CUnit`, so the written values are returned to the caller instead of being
// added to `World`/`SimUnit`.
//
// Recovered dialog-object layout used by the comments: `+0x4e` state byte,
// `+0x58`/`+0x5a` u16 position pair, `+0x5c` live position dword, `+0x74`
// cue argument, `+0xc4`/`+0xc8` saved position, `+0xd3` flag byte and
// `+0xd4` intrusive-list head.
//
// Three rows are pure jump-table data and are deliberately skipped:
// `FUN_005ab7ef`, `FUN_005ab809` and `FUN_005ab8fc`.  The dwords there are
// `0x005a71ff`, `0x005a721c`, `0x005a7236`, ... targets of the
// `0x005a6xxx..=0x005a83xx` handlers, so there is no behaviour to translate.
//
// Retail's failure branches hand control to helpers (`FUN_0058b640`,
// `FUN_0058b650`, `FUN_005b4cd0`) and to the shared epilogue `0x005b8040`; the
// translations report those exits through [`A26Exit`] instead of
// re-implementing the helpers.

// ---------------------------------------------------------------------------
// Shared arithmetic arms
// ---------------------------------------------------------------------------

/// Selector `0` subtracts, `1` adds, `2` XORs.  Any other selector leaves the
/// accumulator untouched, which is what the recovered `jne` chains do when
/// they fall through both `cmp` tests.
fn a26_apply(selector: u32, acc: u32, operand: u32) -> u32 {
    match selector {
        0 => acc.wrapping_sub(operand),
        1 => acc.wrapping_add(operand),
        2 => acc ^ operand,
        _ => acc,
    }
}

/// The mirrored form used by the `+h` step of the recovered chains: selector
/// `0` adds and `1` subtracts.
fn a26_apply_plus(selector: u32, acc: u32, operand: u32) -> u32 {
    match selector {
        0 => acc.wrapping_add(operand),
        1 => acc.wrapping_sub(operand),
        2 => acc ^ operand,
        _ => acc,
    }
}

/// The `+y` seed of the three side chains: selector `0` keeps the value, `1`
/// negates it, `2` keeps it (retail computes `0 ^ y`, which is `y`) and every
/// other selector yields `0`.
fn a26_signed(selector: u32, value: u32) -> u32 {
    match selector {
        0 | 2 => value,
        1 => value.wrapping_neg(),
        _ => 0,
    }
}

impl SimUnit {
    /// `0x005aa074` (`FUN_005aa074`, ledger size 28): subtract arm.
    ///
    /// ```asm
    /// 005aa074  sub eax, edi
    /// 005aa076  jmp 005aa08b
    /// 005aa078  cmp ecx, 2      ; alternate entry, not this one
    /// 005aa07d  xor eax, edi
    /// ```
    ///
    /// The arm is entered when the selector is `0`, so the only operation it
    /// performs is the wrapping 32-bit subtraction `acc - operand`; the
    /// following block spills the result to `/Od` temporaries and keeps it.
    pub fn a26_arith_sub(acc: u32, operand: u32) -> u32 {
        acc.wrapping_sub(operand)
    }

    /// `0x005aa0a3` (`FUN_005aa0a3`, ledger size 32): three-way dispatch.
    ///
    /// ```asm
    /// 005aa0a3  mov  [ebp-0xb0], eax
    /// 005aa0ab  mov  eax, [ebp-0xb0]
    /// 005aa0b1  test ecx, ecx
    /// 005aa0b3  jne  005aa0b7
    /// 005aa0b5  sub  eax, edi
    /// 005aa0b7  cmp  ecx, 1
    /// 005aa0ba  jne  005aa0c0
    /// 005aa0bc  add  eax, edi
    /// 005aa0c0  cmp  ecx, 2          ; selector 2 continues into 0x005aa0c3
    /// ```
    ///
    /// The address is a jump-table target inside the window's `/Od` expression
    /// evaluator.  `ecx` is the selector, `eax` the accumulator and `edi` the
    /// operand.  Selector `0` subtracts, `1` adds and `2` XORs the operand;
    /// anything else leaves the accumulator unchanged.
    pub fn a26_arith_apply(selector: u32, acc: u32, operand: u32) -> u32 {
        a26_apply(selector, acc, operand)
    }

    /// `0x005aa0c3` (`FUN_005aa0c3`, ledger size 291): the XOR arm plus two
    /// more dispatches and the table load that follows them.
    ///
    /// ```asm
    /// 005aa0c3  jne 005aa0c7
    /// 005aa0c5  xor eax, edi          ; first selector == 2
    /// ...
    /// 005aa103  test ebx, ebx ; jne ; sub eax, esi
    /// 005aa10b  cmp  ebx, 1   ; jne ; add eax, esi
    /// 005aa114  cmp  ebx, 2   ; jne ; xor eax, esi
    /// ...
    /// 005aa151  mov  eax, [ebp+0x14] ; test ; sub/add/xor eax, edx
    /// 005aa1a8  mov  ecx, eax
    /// 005aa1ae  mov  eax, [ebp-0x298]
    /// 005aa1b4  mov  eax, [ecx+eax]   ; table[index]
    /// ```
    ///
    /// This label only carries the XOR half of the first dispatch (the
    /// subtract arm is the previous entry), so the first selector is applied
    /// as `if selector == 2 { acc ^= first }`.  The next two dispatches use
    /// the full three-way form and the result indexes the dword table at
    /// `[ebp-0x298]`; the table contents belong to the caller.
    pub fn a26_arith_index(
        first_selector: u32,
        acc: u32,
        first: u32,
        second_selector: u32,
        second: u32,
        third_selector: u32,
        third: u32,
    ) -> u32 {
        let mut value = if first_selector == 2 {
            acc ^ first
        } else {
            acc
        };
        value = a26_apply(second_selector, value, second);
        a26_apply(third_selector, value, third)
    }

    /// `0x005ab70c` (`FUN_005ab70c`, ledger size 81): the folded arithmetic
    /// of a control check whose tail is `int 0x29`.
    ///
    /// ```asm
    /// 005ab70c  jne 005ab712 ; add eax, edi ; jmp 005ab719
    /// 005ab712  cmp edx, 2   ; jne ; xor eax, edi
    /// 005ab719  mov [ebp-0x100], eax
    /// 005ab725  test ebx, ebx ; jne ; sub eax, esi
    /// 005ab72d  cmp  ebx, 1   ; jne ; add eax, esi
    /// 005ab736  cmp  ebx, 2   ; jne ; xor eax, esi
    /// 005ab749  int  0x29                       ; __fastfail
    /// 005ab74b  mov  ecx, [ebp-0x10]            ; SEH epilogue
    /// ```
    ///
    /// Two selector/operand pairs are folded into one value and the path then
    /// executes `int 0x29` (`__fastfail`), so retail never returns.  The
    /// helper returns the folded value so the recovered arithmetic stays
    /// observable; callers must treat the path as terminal.
    ///
    /// The first dispatch's default arm is the `add` at `0x005ab70e`, hence
    /// the mirrored `+`/`-` table for the first selector.
    pub fn a26_guard_fold(
        first_selector: u32,
        acc: u32,
        first: u32,
        second_selector: u32,
        second: u32,
    ) -> u32 {
        let value = a26_apply_plus(first_selector, acc, first);
        a26_apply(second_selector, value, second)
    }
}

// ---------------------------------------------------------------------------
// 0x005aae8d - bounding block of the dialog object
// ---------------------------------------------------------------------------

/// Selectors used by the four `0x005aae8d` chains.
///
/// The chains are entered with selectors in registers (`esi` for `+0x20`/`w`,
/// `ebx` for `+0x28`/`h` and the `[ebp+0x14]` argument for the `y` pair), so
/// the translation exposes them instead of guessing the shipped values.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct A26FieldOps {
    /// Selector applied to the `+0x20` operand.
    pub w: u32,
    /// Selector applied to the `+0x28` operand.
    pub h: u32,
    /// Selector applied to the `+0x14` operand.
    pub y: u32,
}

impl SimUnit {
    /// `0x005aae8d` (`FUN_005aae8d`, ledger size 1041): the four recovered
    /// field chains of the dialog object at `[ebp-0x104]`.
    ///
    /// The first chain (`0x005aae8d`..`0x005ab00c`) writes `+0xa0`:
    ///
    /// ```asm
    /// 005aae8d  sub  eax, edi              ; apply(w, x, w)
    /// 005aaec9  add  eax, ecx              ; + h   (ebx == 0)
    /// 005aaf0b  sub  eax, ecx              ; - h   (ebx == 0)
    /// 005aaf5f  sub  eax, edi              ; - w   (esi == 0)
    /// 005aafb6  sub  eax, edx              ; - y   ([ebp+0x14] == 0)
    /// 005ab00c  mov  [eax+0xa0], ecx
    /// ```
    ///
    /// Three further chains write `+0x9c` (store at `0x005ab1ea`), `+0xb0`
    /// (`0x005ab3c8`) and `+0xb8`; each starts with
    /// `a26_signed([ebp+0x14], y)` and then repeats `+w`, `+h`, `-h`, `-w`,
    /// `-y`.  The three chains are instruction-for-instruction identical, so
    /// they always produce the same value; the return array keeps the store
    /// order `[+0x9c, +0xa0, +0xb0, +0xb8]` anyway.
    ///
    /// A consequence worth recording: every step of a side chain is undone by
    /// a later step with the same selector (including the `^` selector, which
    /// cancels itself), so `+0x9c`, `+0xb0` and `+0xb8` are always zero and
    /// the routine effectively clears them and writes `x - 2w - y` into
    /// `+0xa0`.  The chains are transcribed instead of hard-coded so the
    /// recovered shape stays reviewable.
    pub fn a26_rect_fields(x: i32, y: i32, w: i32, h: i32, ops: A26FieldOps) -> [i32; 4] {
        let (x, y, w, h) = (x as u32, y as u32, w as u32, h as u32);

        let mut top = a26_apply(ops.w, x, w);
        top = a26_apply_plus(ops.h, top, h);
        top = a26_apply(ops.h, top, h);
        top = a26_apply(ops.w, top, w);
        top = a26_apply(ops.y, top, y);

        let mut side = a26_signed(ops.y, y);
        side = a26_apply_plus(ops.w, side, w);
        side = a26_apply_plus(ops.h, side, h);
        side = a26_apply(ops.h, side, h);
        side = a26_apply(ops.w, side, w);
        side = a26_apply(ops.y, side, y);

        [side as i32, top as i32, side as i32, side as i32]
    }
}

// ---------------------------------------------------------------------------
// Dialog / briefing object transitions
// ---------------------------------------------------------------------------

/// Argument a recovered dialog cue is queued with.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A26CueArg {
    /// The `+0x74` cue slot (`FUN_005b74f0(id, arg)`); the zero case is the
    /// `FUN_005b6ca0(id, 0)` variant.
    Slot(u32),
    /// The live `+0x58`/`+0x5c` pair (`FUN_005b72e0`).
    LivePosition,
    /// The linked dialog handle (`FUN_005b7250`).
    Handle,
    /// Queued with the id alone (`FUN_005b7d00`).
    NoArgument,
}

/// How a recovered dialog tick leaves.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A26Exit {
    /// Falls out through the routine's own `ret`.
    Return,
    /// Tail-jumps to the shared `0x005b8040` epilogue.
    Finish,
    /// Runs the `FUN_005d9480` disposal and then the shared epilogue.
    Dispose,
}

/// One recovered dialog-tick outcome.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct A26Dialog {
    /// Value written back to the `+0x4e` state byte, when the arm writes one.
    pub state: Option<u8>,
    /// `+0x58`/`+0x5c` copied into the saved position `+0xc4`/`+0xc8`.
    pub latch: bool,
    /// Cue queued before the state work (`0x97`), with its argument.
    pub preroll: Option<(u16, A26CueArg)>,
    /// Cue queued by the state arm, with its argument.
    pub cue: Option<(u16, A26CueArg)>,
    /// How the routine leaves.
    pub exit: A26Exit,
}

impl A26Dialog {
    /// No write, no cue, plain `ret`.
    pub const IDLE: Self = Self {
        state: None,
        latch: false,
        preroll: None,
        cue: None,
        exit: A26Exit::Return,
    };
}

/// Selector for the two clamped entry points of the dialog tail.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A26DialogDispatch {
    /// The id is above the entry's limit: retail restores the saved position
    /// from `+0xc4`/`+0xc8` and aborts when both halves are zero.
    RestorePosition,
    /// State `0`: latch the live position and advance to state `1`.
    Latch,
    /// State `1`: run the engagement checks and move to state `3`.
    Engage,
    /// State `2`: the already-engaged arm.
    Engaged,
    /// Any other state byte: the dispatcher returns without a write.
    Idle,
}

impl World {
    /// `0x005aba57` (`FUN_005aba57`, ledger size 217): one tick of the
    /// briefing/transmission dialog.
    ///
    /// The recorded address is one byte inside the `push 0x97` immediate of
    /// the routine body (`0x005aba58` is the call target); the routine's
    /// prologue is not a ledger row.  The recovered body is:
    ///
    /// ```asm
    /// 005aba20  push ebx/esi/edi ; mov esi, ecx ; mov edi, [esi+0x5c]
    /// 005aba28  call FUN_005b58c0 ; jne 005abb1f        ; forced cleanup
    /// 005aba37  call FUN_005bb950 ; jne 005aba6b        ; skip the pre-roll
    /// 005aba44  call FUN_005bd4a0(this, 1)
    /// 005aba49  eax = [esi+0x74]
    /// 005aba58  call FUN_005b74f0(0x97, eax) / 005b6ca0(0x97, 0)
    /// 005aba6b  al = [esi+0x4e]
    /// 005aba70  je  005abad2                          ; state 0
    /// 005aba74  cmp al, 3 ; jne ret                   ; other states
    /// ...       state 3: FUN_005bb740, FUN_005ad8f0, FUN_005b5620
    /// 005abad2  state 0: FUN_005ad980 -> cue 0x55 + x/y
    ///                     else FUN_005d8f30 -> latch + state 3
    /// 005abb1f  call FUN_005d9480 ; jmp 0x005b8040      ; disposal
    /// ```
    ///
    /// `forced_cleanup` is the `FUN_005b58c0 != 0` result, `preroll_suppressed`
    /// the `FUN_005bb950 != 0` result (the `0x97` cue is skipped, together with
    /// the `FUN_005bd4a0(this, 1)` call), `cue_slot` the `+0x74` value,
    /// `acquire_ok` the `FUN_005ad980` result, `view_ok` the `FUN_005d8f30`
    /// result, `engage` the `FUN_005bb740` value (`0` returns immediately, `2`
    /// resets the state), `target_ok` the `FUN_005ad8f0` result and `overlay`
    /// the `FUN_005b5620` result.
    #[allow(clippy::too_many_arguments)]
    pub fn a26_transmission_tick(
        state: u8,
        has_link: bool,
        forced_cleanup: bool,
        preroll_suppressed: bool,
        cue_slot: u32,
        acquire_ok: bool,
        view_ok: bool,
        engage: u8,
        target_ok: bool,
        overlay: bool,
    ) -> A26Dialog {
        let mut out = A26Dialog::IDLE;
        if forced_cleanup {
            out.exit = A26Exit::Dispose;
            return out;
        }
        if !preroll_suppressed {
            out.preroll = Some((0x97, A26CueArg::Slot(cue_slot)));
        }
        match state {
            0 => {
                if !has_link {
                    out.exit = A26Exit::Dispose;
                    return out;
                }
                if acquire_ok {
                    out.cue = Some((0x55, A26CueArg::LivePosition));
                    out.exit = A26Exit::Finish;
                    return out;
                }
                if view_ok {
                    out.state = Some(3);
                    out.latch = true;
                }
            }
            3 => {
                if engage == 0 {
                    return out;
                }
                if !has_link || !target_ok {
                    out.exit = A26Exit::Dispose;
                    return out;
                }
                if engage == 2 {
                    out.state = Some(0);
                    return out;
                }
                if overlay {
                    out.cue = Some((0x54, A26CueArg::NoArgument));
                } else {
                    out.cue = Some((0x52, A26CueArg::Handle));
                    out.exit = A26Exit::Finish;
                }
            }
            _ => {}
        }
        out
    }

    /// `0x005abf29` (`FUN_005abf29`, ledger size 17): lowest accepted dialog
    /// id.
    ///
    /// ```asm
    /// 005abf29  mov  ecx, 0xb0
    /// 005abf2e  cmp  ax, cx
    /// 005abf31  ja   005abf49        ; saved-position restore arm
    /// 005abf33  mov  ecx, edi
    /// 005abf35  call FUN_005b4cd0      ; precondition, then fall into 0x005abf3a
    /// ```
    ///
    /// Ids at or below `0xb0` run the `FUN_005b4cd0` precondition and then the
    /// state dispatch; larger ids take the restore arm.  The sibling entry at
    /// `0x005abf3a` uses the wider `0xb2` bound, see
    /// [`World::a26_dialog_dispatch`].
    pub fn a26_dialog_arg_fits_low(arg: u16) -> bool {
        arg <= 0xb0
    }

    /// `0x005abf3a` (`FUN_005abf3a`, ledger size 56): second clamp plus the
    /// three-case state dispatch.
    ///
    /// ```asm
    /// 005abf3a  mov  ecx, 0xb2
    /// 005abf40  cmp  ax, cx
    /// 005abf43  ja   005abf49        ; restore saved position
    /// 005abf44  mov  al, [esi+0x4e]
    /// 005abf47  jmp  005abfb7        ; switch (state)
    /// 005abfb7  movzx eax, al ; sub eax, 0 ; je 005ac10b   ; state 0
    /// 005abfc4  sub  eax, 1   ; je 005abfd5                ; state 1
    /// 005abfc9  sub  eax, 2   ; je 005ac047                ; state 2
    /// 005abfce  pop/pop/pop ; ret                           ; other states
    /// ```
    ///
    /// The two clamped entries share this body; only the bound and the
    /// `FUN_005b4cd0` precondition differ.
    pub fn a26_dialog_dispatch(arg: u16, state: u8) -> A26DialogDispatch {
        if arg > 0xb2 {
            return A26DialogDispatch::RestorePosition;
        }
        match state {
            0 => A26DialogDispatch::Latch,
            1 => A26DialogDispatch::Engage,
            2 => A26DialogDispatch::Engaged,
            _ => A26DialogDispatch::Idle,
        }
    }

    /// `0x005abf6f` (`FUN_005abf6f`, ledger size 57): operand selection for
    /// the lookup at `FUN_005c6970`.
    ///
    /// ```asm
    /// 005abf6f  mov  [ebp-2], ax          ; the u16 argument is parked
    /// 005abf73  mov  eax, [ebp-4]         ; this entry uses the local dword
    /// 005abf76  jmp  005abf86
    /// 005abf78  mov  eax, [esi+0xc4]      ; alternate entry
    /// 005abf7e  xor  ecx, ecx
    /// 005abf80  mov  [esi+0xc4], ecx      ; clears the saved position
    /// 005abf86  push eax ; mov ecx, esi ; call FUN_005c6970
    /// 005abf8e  mov  edi, eax ; test ; jne abort   ; error -> +0x5c, abort
    /// ```
    ///
    /// Returns the operand handed to `FUN_005c6970` and whether the alternate
    /// arm cleared `+0xc4`.  `stored` is `None` for this entry's own arm and
    /// `Some(value)` for the alternate one.
    pub fn a26_dialog_lookup_operand(local: u32, stored: Option<u32>) -> (u32, bool) {
        match stored {
            Some(value) => (value, true),
            None => (local, false),
        }
    }

    /// `0x005abfad` (`FUN_005abfad`, ledger size 127): the reset arm.
    ///
    /// ```asm
    /// 005abfad  mov  [esi+0x5a], ax
    /// 005abfb1  xor  al, al
    /// 005abfb3  mov  [esi+0x4e], 0        ; state = 0
    /// 005abfb7  movzx eax, al
    /// 005abfba  sub  eax, 0
    /// 005abfbd  je   005ac10b             ; always case 0
    /// 005ac10b  push [esi+0x5c] ; call FUN_005d8f30
    /// 005ac117  je   005abfcf             ; no write, ret
    /// 005ac11d  mov  [esi+0xc4], [esi+0x58]
    /// 005ac12a  mov  [esi+0xc8], [esi+0x5c]
    /// 005ac130  mov  [esi+0x4e], 1
    /// ```
    ///
    /// The u16 argument is stored in the `+0x5a` half of the position pair
    /// before the state is zeroed.  `view_ok` is the `FUN_005d8f30` result; a
    /// hit latches the live position and leaves state `1`, a miss leaves the
    /// zeroed state untouched.
    pub fn a26_dialog_reset(view_ok: bool) -> A26Dialog {
        let mut out = A26Dialog::IDLE;
        out.state = Some(0);
        if view_ok {
            out.state = Some(1);
            out.latch = true;
        }
        out
    }
}

#[cfg(test)]
mod tests_agent26 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn open_world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World, x: i32, y: i32) -> usize {
        world.spawn_px(0, uid::MARINE, x, y).unwrap()
    }

    #[test]
    fn arith_sub_is_wrapping_subtraction() {
        let mut w = open_world();
        let i = spawn(&mut w, 20, 10);
        let unit = &w.units[i];
        assert_eq!(
            SimUnit::a26_arith_sub(unit.x as u32, 3),
            (unit.x as u32) - 3
        );
        assert_eq!(SimUnit::a26_arith_sub(10, 3), 7);
        assert_eq!(SimUnit::a26_arith_sub(0, 1), u32::MAX);
    }

    #[test]
    fn arith_apply_selects_sub_add_xor() {
        let w = open_world();
        assert_eq!(w.units.len(), 0);
        assert_eq!(SimUnit::a26_arith_apply(0, 10, 4), 6);
        assert_eq!(SimUnit::a26_arith_apply(1, 10, 4), 14);
        assert_eq!(SimUnit::a26_arith_apply(2, 0b1010, 0b0110), 0b1100);
        // Selectors outside 0..=2 fall through both compares.
        assert_eq!(SimUnit::a26_arith_apply(3, 10, 4), 10);
    }

    #[test]
    fn arith_index_folds_three_selectors() {
        let mut w = open_world();
        let i = spawn(&mut w, 32, 32);
        let base = w.units[i].x as u32;
        assert_eq!(
            SimUnit::a26_arith_index(0, base, 0x08, 0, 4, 1, 2),
            base - 4 + 2
        );
        // The label itself only XORs on the first selector's `2` arm.
        assert_eq!(
            SimUnit::a26_arith_index(2, 0xff, 0x0f, 1, 1, 2, 1),
            ((0xff ^ 0x0f) + 1) ^ 1
        );
        assert_eq!(SimUnit::a26_arith_index(1, 0xff, 0x0f, 0, 0, 0, 0), 0xff);
    }

    #[test]
    fn rect_fields_reproduce_the_recovered_chains() {
        let mut w = open_world();
        let i = spawn(&mut w, 320, 288);
        let unit = &w.units[i];
        let (x, y) = (unit.x, unit.y);
        let (wd, ht) = (8, 4);

        let f = SimUnit::a26_rect_fields(x, y, wd, ht, A26FieldOps::default());
        // +0xa0 = x - w + h - h - w - y.
        assert_eq!(f[1], x - 2 * wd - y);
        // The three side chains cancel for every selector.
        assert_eq!((f[0], f[2], f[3]), (0, 0, 0));

        for ops in [
            A26FieldOps { w: 1, h: 0, y: 0 },
            A26FieldOps { w: 0, h: 1, y: 0 },
            A26FieldOps { w: 0, h: 0, y: 1 },
            A26FieldOps { w: 2, h: 2, y: 2 },
            A26FieldOps { w: 1, h: 1, y: 1 },
        ] {
            let f = SimUnit::a26_rect_fields(x, y, wd, ht, ops);
            assert_eq!((f[0], f[2], f[3]), (0, 0, 0), "{ops:?}");
        }

        // With all three selectors flipped both `w` steps add, so the
        // `+0xa0` chain becomes `x + 2w + y`.
        let flipped = SimUnit::a26_rect_fields(x, y, wd, ht, A26FieldOps { w: 1, h: 1, y: 1 });
        assert_eq!(flipped[1], x + 2 * wd + y);
    }

    #[test]
    fn guard_fold_matches_the_fastfail_arithmetic() {
        let mut w = open_world();
        let i = spawn(&mut w, 64, 64);
        assert!(w.units[i].alive);
        // (5 + 3) - 2, the first dispatch's default arm is `add`.
        assert_eq!(SimUnit::a26_guard_fold(0, 5, 3, 0, 2), 6);
        // (5 - 3) + 2.
        assert_eq!(SimUnit::a26_guard_fold(1, 5, 3, 1, 2), 4);
        // (0b1100 ^ 0b1010) ^ 0b0011.
        assert_eq!(
            SimUnit::a26_guard_fold(2, 0b1100, 0b1010, 2, 0b0011),
            0b0110 ^ 0b0011
        );
        // Unused selectors leave the accumulator alone.
        assert_eq!(SimUnit::a26_guard_fold(7, 9, 4, 7, 4), 9);
    }

    #[test]
    fn transmission_tick_state_zero_arms() {
        let mut w = open_world();
        let i = spawn(&mut w, 320, 288);
        assert_eq!(w.units[i].y, 288 * 256);

        // The forced cleanup at 0x005abb1f wins over everything.
        let out =
            World::a26_transmission_tick(0, true, true, false, 0x11, true, true, 1, true, false);
        assert_eq!(out.exit, A26Exit::Dispose);
        assert_eq!(out.preroll, None);

        // No linked dialog: state 0 disposes.
        let out =
            World::a26_transmission_tick(0, false, false, true, 0, false, false, 0, false, false);
        assert_eq!(out.exit, A26Exit::Dispose);

        // Acquire path queues 0x55 with the live position and finishes.
        let out =
            World::a26_transmission_tick(0, true, false, true, 0, true, false, 0, false, false);
        assert_eq!(out.cue, Some((0x55, A26CueArg::LivePosition)));
        assert_eq!(out.exit, A26Exit::Finish);
        assert_eq!(out.state, None);

        // View predicate latches the position and advances to state 3.
        let out =
            World::a26_transmission_tick(0, true, false, true, 0, false, true, 0, false, false);
        assert_eq!(out.state, Some(3));
        assert!(out.latch);
        assert_eq!(out.exit, A26Exit::Return);

        // Neither predicate: plain return.
        let out =
            World::a26_transmission_tick(0, true, false, true, 0, false, false, 0, false, false);
        assert_eq!(out, A26Dialog::IDLE);

        // The 0x97 pre-roll rides in front of the state work.
        let out = World::a26_transmission_tick(
            0, true, false, false, 0x2a, false, false, 0, false, false,
        );
        assert_eq!(out.preroll, Some((0x97, A26CueArg::Slot(0x2a))));
    }

    #[test]
    fn transmission_tick_state_three_arms() {
        let w = open_world();
        assert_eq!(w.players.len(), 2);

        // engage == 0 returns before the link checks.
        let out =
            World::a26_transmission_tick(3, false, false, true, 0, false, false, 0, false, false);
        assert_eq!(out, A26Dialog::IDLE);

        // Missing link or failed target check disposes.
        let out =
            World::a26_transmission_tick(3, false, false, true, 0, false, false, 1, true, false);
        assert_eq!(out.exit, A26Exit::Dispose);
        let out =
            World::a26_transmission_tick(3, true, false, true, 0, false, false, 1, false, false);
        assert_eq!(out.exit, A26Exit::Dispose);

        // engage == 2 falls back to state 0.
        let out =
            World::a26_transmission_tick(3, true, false, true, 0, false, false, 2, true, false);
        assert_eq!(out.state, Some(0));
        assert_eq!(out.exit, A26Exit::Return);

        // FUN_005b5620 selects the overlay cue.
        let out =
            World::a26_transmission_tick(3, true, false, true, 0, false, false, 1, true, true);
        assert_eq!(out.cue, Some((0x54, A26CueArg::NoArgument)));
        assert_eq!(out.exit, A26Exit::Return);

        let out =
            World::a26_transmission_tick(3, true, false, true, 0, false, false, 1, true, false);
        assert_eq!(out.cue, Some((0x52, A26CueArg::Handle)));
        assert_eq!(out.exit, A26Exit::Finish);

        // Other states fall through the al == 0 / al == 3 tests.
        let out = World::a26_transmission_tick(7, true, false, true, 0, true, true, 2, true, true);
        assert_eq!(out, A26Dialog::IDLE);
    }

    #[test]
    fn dialog_arg_bound_is_zero_b0() {
        let mut w = open_world();
        let i = spawn(&mut w, 32, 32);
        assert!(w.units[i].alive);
        assert!(World::a26_dialog_arg_fits_low(0));
        assert!(World::a26_dialog_arg_fits_low(0xb0));
        assert!(!World::a26_dialog_arg_fits_low(0xb1));
        assert!(!World::a26_dialog_arg_fits_low(0xffff));
    }

    #[test]
    fn dialog_dispatch_uses_the_b2_bound_and_state() {
        let w = open_world();
        assert_eq!(w.units.len(), 0);
        assert_eq!(
            World::a26_dialog_dispatch(0xb2, 0),
            A26DialogDispatch::Latch
        );
        assert_eq!(
            World::a26_dialog_dispatch(0xb2, 1),
            A26DialogDispatch::Engage
        );
        assert_eq!(
            World::a26_dialog_dispatch(0xb2, 2),
            A26DialogDispatch::Engaged
        );
        assert_eq!(World::a26_dialog_dispatch(0xb2, 3), A26DialogDispatch::Idle);
        // One past the second bound restores the saved position.
        assert_eq!(
            World::a26_dialog_dispatch(0xb3, 0),
            A26DialogDispatch::RestorePosition
        );
        assert_eq!(
            World::a26_dialog_dispatch(0x0200, 2),
            A26DialogDispatch::RestorePosition
        );
    }

    #[test]
    fn dialog_lookup_operand_prefers_local_and_clears_stored() {
        let mut w = open_world();
        let i = spawn(&mut w, 32, 32);
        let id = w.units[i].id;
        assert_eq!(World::a26_dialog_lookup_operand(id, None), (id, false));
        assert_eq!(
            World::a26_dialog_lookup_operand(id, Some(0x99)),
            (0x99, true)
        );
    }

    #[test]
    fn dialog_reset_reaches_case_zero() {
        let mut w = open_world();
        let i = spawn(&mut w, 32, 32);
        assert_eq!(w.units[i].owner, 0);

        let hit = World::a26_dialog_reset(true);
        assert_eq!(hit.state, Some(1));
        assert!(hit.latch);
        assert_eq!(hit.exit, A26Exit::Return);

        let miss = World::a26_dialog_reset(false);
        assert_eq!(miss.state, Some(0));
        assert!(!miss.latch);
        assert_eq!(miss.exit, A26Exit::Return);
    }
}

