///     if ((local_2c == 0) || (0x14 < local_34) || (4 < local_30)) FUN_0093ec70();
///     local_8 = CONCAT31(local_8._1_3_, 1);             /* stage = 1     */
///     (**(code **)(*param_1 + 0x10))(local_28);        /* builder       */
/// }
/// FUN_005426e0(local_28);                            /* non-returning */
