        assert_eq!(a68_timeline_advance(120, 0).total, 0);
        assert_eq!(a68_timeline_advance(-120, 0).ids, vec![0x12]);
        assert_eq!(a68_timeline_advance(0, 0).ids, Vec::<u16>::new());
