    #[test]
    fn heap_sort_matches_an_ascending_sort() {
        let cases: [&[u32]; 5] = [
            &[],
            &[42],
            &[2, 1],
            &[5, 5, 1, 9, 3, 3, 0],
            &[9, 8, 7, 6, 5, 4, 3, 2, 1, 0, 11, 12],
        ];
        for case in cases {
            let mut sorted = case.to_vec();
            sorted.sort_unstable();
            let mut heaped = case.to_vec();
            a79_heap_sort(&mut heaped);
            assert_eq!(heaped, sorted, "input {case:?}");
        }
    }

