        let samples = [(0u32, 0u32), (2000, 0)];
        assert_eq!(a79_timing_stats_or_zero(&samples, 0), [0.0; 4]);
        assert_eq!(a79_timing_stats_or_zero(&samples, 2), [0.002; 4]);
