        let pointer = 0x00fa_c940 + 5 * 0x18;
        assert_eq!(a84_slot_id_from_pointer(pointer), 6);
        assert_eq!(a84_slot_id_from_pointer(0x00fa_c940), 1);
        assert_eq!(a84_slot_id_from_pointer(0), 0);
