        let mut state = W14a09ScrollState {
            x: 5,
            prev_x: 5,
            tile_x: 0,
            last_tile_x: 9,
            ..W14a09ScrollState::default()
        };
        let mut layers = W14a09Parallax::default();

        let result = w14a09_scroll_left(&mut state, &mut layers, 20, &[1; 5], 97, 1.0);

