        assert_eq!(w24a01_probe_channels(1, 1, |_| true), Some((4, 1)));
        assert_eq!(w24a01_probe_channels(1, 2, |_| true), Some((3, 2)));
        assert_eq!(w24a01_probe_channels(1, 2, |i| i < 2), None);
